async function passwordDigest(password,saltValue){
 if(!window.crypto?.subtle||!window.crypto?.getRandomValues)throw new Error('Browser belum mendukung penyimpanan kata sandi lokal yang lebih aman. Gunakan mode tamu atau perbarui browser.');
 const salt=saltValue?Uint8Array.from(atob(saltValue),c=>c.charCodeAt(0)):window.crypto.getRandomValues(new Uint8Array(16));
 const key=await window.crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);
 const bits=await window.crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:120000,hash:'SHA-256'},key,256);
 return {salt:btoa(String.fromCharCode(...salt)),hash:btoa(String.fromCharCode(...new Uint8Array(bits)))};
}
async function registerAccount(form){
 const data=new FormData(form),name=String(data.get('name')||'').trim(),email=String(data.get('email')||'').trim().toLowerCase(),password=String(data.get('password')||''),confirm=String(data.get('confirm')||'');
 if(name.length<2){state.authError='Nama lengkap minimal terdiri dari 2 karakter.';renderAuth('signup');return;}
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){state.authError='Masukkan alamat email yang valid.';renderAuth('signup');return;}
 if(password.length<8){state.authError='Kata sandi minimal 8 karakter.';renderAuth('signup');return;}
 if(password!==confirm){state.authError='Kata sandi dan konfirmasi belum sama.';renderAuth('signup');return;}
 if((state.auth?.type==='account'&&state.auth.email)||(state.auth?.savedAccount?.email)){state.authError='Sudah ada akun demo di browser ini. Silakan masuk menggunakan akun tersebut.';renderAuth('signup');return;}
 try{
  const digest=await passwordDigest(password);
  state.auth={type:'account',name,email,salt:digest.salt,passwordHash:digest.hash,loggedIn:true,createdAt:new Date().toISOString()};
  state.authError='';state.seen=false;state.route='home';location.hash='home';persist();activity('Membuat akun ModalMatch.');render();toast('Akun demo berhasil dibuat. Selamat datang, '+name+'!');
 }catch(err){state.authError=err.message||'Akun belum dapat dibuat di browser ini.';renderAuth('signup');}
}
async function loginAccount(form){
 const data=new FormData(form),email=String(data.get('email')||'').trim().toLowerCase(),password=String(data.get('password')||'');
 const accountRecord=state.auth?.type==='account'?state.auth:state.auth?.savedAccount;
 if(!accountRecord||accountRecord.type!=='account'){state.authError='Belum ada akun demo di browser ini. Buat akun terlebih dahulu.';renderAuth('login');return;}
 if(email!==accountRecord.email){state.authError='Email tidak ditemukan pada browser ini.';renderAuth('login');return;}
 try{
  const digest=await passwordDigest(password,accountRecord.salt);
  if(digest.hash!==accountRecord.passwordHash){state.authError='Kata sandi belum sesuai. Coba periksa kembali.';renderAuth('login');return;}
  state.auth={...accountRecord,loggedIn:true};state.authError='';state.route='home';location.hash='home';persist();render();toast('Berhasil masuk. Selamat datang kembali, '+currentUserName()+'.');
 }catch(err){state.authError=err.message||'Tidak dapat memverifikasi akun demo.';renderAuth('login');}
}
