function renderRoute(){return ({home:homeView,finder:finderView,results:resultsView,catalog:catalogView,compare:compareView,analysis:analysisView,reports:reportsView,profile:profileView,sources:sourcesView,revenue:revenueView,funding:fundingView,help:helpView}[state.route]||homeView)();}
function homeView(){const h=E.health(state.profile),ratio=Math.round(h.capacity/(state.profile.category==='pribadi'?state.profile.income:state.profile.revenue)*100);
 const featured=['bca-personal','cimb-xtra-dana','mandiri-kur-mikro'].map(id=>PRODUCTS.find(p=>p.id===id));
 return `${heading(`Halo, ${esc(currentUserName())} <span style="font-weight:400">✦</span>`,'Satu langkah lebih dekat ke keputusan finansial yang tepat. Isi profilmu agar hasil simulasi lebih relevan.',`<span class="tag outline">${icon('clock','sm')} Data diperiksa 7 Nov 2026</span>`)}<div class="home-top"><section class="panel hero"><div class="hero-grid"></div><div class="hero-content"><div class="eyebrow">KENALI PILIHAN. TEMUKAN ARAH.</div><h2>Pembiayaan yang tepat,<br><span>berawal dari kamu.</span></h2><p>Jelajahi pilihan bank, pahami biayanya, dan temukan yang sesuai kemampuanmu.</p>${button('Cari pembiayaan '+icon('arrow','sm'),'start-finder')}</div>${compass()}</section><section class="panel health-card"><div class="row between"><span class="eyebrow">KAPASITAS ANGSURANMU</span>${icon('shield','sm')}</div><div class="health-main"><div class="health-ring"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="42" fill="none" stroke="#eef2ef" stroke-width="7"/><circle cx="50" cy="50" r="42" fill="none" stroke="#338f76" stroke-width="7" stroke-dasharray="${Math.min(ratio,100)*2.64} 264" stroke-linecap="round"/></svg><div class="center"><strong>${ratio}%</strong><span class="muted tiny">dari ${state.profile.category==='pribadi'?'gaji':'omzet'}</span></div></div><div class="health-text"><strong>${rupiah(h.capacity)}</strong><small>per bulan · berdasarkan profil demo</small><span class="tag green" style="margin-top:10px">${icon('check','sm')} Batas perencanaan</span></div></div><div class="divider"></div><div class="footer"><span>Bukan batas persetujuan bank</span><button class="btn link" style="font-size:10px;padding:0" data-route="analysis">Lihat analisis ${icon('arrow','sm')}</button></div></section></div><div class="stats-strip">${[['building','10','Bank dalam riset'],['grid','19','Produk aktif'],['shield','100%','Produk dengan sumber'],['wallet','Gratis','Pencarian & simulasi']].map(([i,n,l])=>`<div class="stat-mini"><div class="stat-icon">${icon(i)}</div><div><strong>${n}</strong><small>${l}</small></div></div>`).join('')}</div><div class="section-head"><div><h2>Apa rencana besarmu?</h2><p>Pilih pembiayaan sesuai kebutuhanmu.</p></div></div><div class="category-grid">${[['briefcase','Kredit pribadi','KTA & kebutuhan personal','pribadi'],['building','Modal usaha','KUR & pembiayaan UMKM','umkm'],['home','Hunian impian','KPR & pembiayaan rumah','roadmap'],['car','Kendaraan','Pembiayaan kendaraan','roadmap']].map(([i,t,d,a])=>`<button class="category-card" data-action="category" data-value="${a}">${a==='roadmap'?'<span class="tag outline">Segera hadir</span>':''}<div class="cat-icon">${icon(i)}</div><h3>${t}</h3><p>${d}</p><span class="arrow">${icon('arrow','sm')}</span></button>`).join('')}</div>${fundingPromoView()}<div class="two-col"><section class="home-products"><div class="section-head"><div><h2>Kenali pilihan pembiayaan</h2><p>Produk riil, dengan informasi yang bisa kamu telusuri.</p></div><button class="btn link" data-route="catalog">Lihat semua ${icon('arrow','sm')}</button></div><div class="product-grid">${featured.map(p=>productCard(p,false,true)).join('')}</div><div class="hint mt">${icon('info','sm')} Bunga mulai bukan penawaran pasti. Biaya yang belum tersedia selalu ditandai dan perlu dikonfirmasi ke bank.</div></section><aside class="home-side">${sponsorView()}<div class="learning-list"><div class="section-head"><h3>Pojok edukasi finansial</h3>${icon('book','sm')}</div>${[['Bunga flat vs. efektif','3 menit · Dasar pembiayaan','flat'],['Kenali biaya di balik cicilan','4 menit · Perencanaan','cost'],['Omzet bukan kemampuan bayar','3 menit · Keuangan usaha','umkm']].map(([t,s,id])=>`<button class="learning-item" data-action="article" data-id="${id}"><span class="learn-icon">${icon('book','sm')}</span><div><h4>${t}</h4><small>${s}</small></div>${icon('chevron','sm')}</button>`).join('')}</div></aside></div><p class="disclaimer">ModalMatch adalah prototipe pendukung keputusan, bukan bank atau pemberi persetujuan kredit. Tidak ada kemitraan bank atau transaksi uang sungguhan.</p>`;
}
function sponsorView(){return `<div class="sponsor boost-sponsor"><span class="tag amber">CONTOH BOOST · SIMULASI</span><h3>Produk mitra dapat tampil lebih terlihat.</h3><p>Bank dapat membayar biaya promosi agar produk pembiayaannya memperoleh slot khusus di ModalMatch.</p>${button('Cara kerja Boost Produk Bank '+icon('arrow','sm'),'sponsor')}<span class="sponsor-art">${icon('building')}</span><small>Contoh tampilan promosi. Belum menunjukkan bank yang telah membayar atau menjadi mitra.</small></div>`;}
function productCard(p,showMatch=false,compact=false){const m=E.match(p,state.profile),c=m.cost;let rate=p.rateByTenor?`${number(p.rateByTenor[36]??p.rateMonthly)}%`:p.rateMonthly!=null?`${number(p.rateMonthly)}%`:p.rateAnnual!=null?`${number(p.rateAnnual)}%`:null;
 return `<article class="product-card"><div class="product-card-top">${bankLogo(p)}<div><h3>${esc(p.name)}</h3><small>${esc(p.bank)} · ${p.category==='pribadi'?'Kredit pribadi':'UMKM'}</small></div><button class="save-btn ${state.saved.includes(p.id)?'saved':''}" data-action="save" data-id="${p.id}" aria-label="${state.saved.includes(p.id)?'Hapus simpan':'Simpan'} ${esc(p.name)}">${icon('bookmark','sm')}</button></div>${showMatch?statusTag(m):`<span class="tag ${p.active?'green':'outline'}" style="align-self:flex-start">${icon('shield','sm')} ${p.active?'Sumber resmi diperiksa':'Arsip · tidak aktif'}</span>`}<div style="margin-top:15px"><div class="rate-label">${showMatch?'Estimasi angsuran / bulan':p.rateIsStarting||p.category==='umkm'?'Bunga ilustrasi mulai':'Bunga publikasi'}</div><div class="rate-value ${(!rate&&!showMatch)||(showMatch&&c.installment===null)?'long':''}">${showMatch?(c.installment===null?'Perlu konfirmasi':rupiah(c.installment)):rate?`${rate} <span>/ ${p.rateMonthly!=null?'bulan':'tahun'}</span>`:'Konfirmasi bank'}</div><div class="tiny muted">${showMatch?'Berdasarkan nominal & tenor profil':p.rateMonthly!=null?'Flat / indikasi setara flat':p.rateAnnual!=null?'Efektif · model anuitas':'Tarif individual belum tersedia'}</div></div><div class="card-facts"><div><small>Plafon hingga</small><strong>${p.maxAmount?'Rp'+short(p.maxAmount):'Konfirmasi'}</strong></div><div><small>Tenor hingga</small><strong>${p.maxTenor?`${p.maxTenor} bulan`:'Konfirmasi'}</strong></div></div><p class="card-note">${showMatch?esc(m.failed[0]||m.passed[0]||'Produk relevan; parameter belum lengkap.'):p.id==='bca-personal'?'Tarif retail 36 bulan. Bunga berbeda per tenor.':esc(p.rateConditional?'Bersyarat; tarif & kelayakan dikonfirmasi bank.':'Ketentuan mengikuti profil dan keputusan bank.')}<br>Biaya belum lengkap${p.stale?' · Dokumen 2024':''}.</p><div class="card-actions"><label class="compare-check"><input type="checkbox" data-compare="${p.id}" ${state.compare.includes(p.id)?'checked':''} ${!p.active?'disabled':''}>Bandingkan</label>${button('Detail '+icon('arrow','sm'),'detail','soft small',`data-id="${p.id}"`)}</div></article>`;
}
function field(key,label,type='money',hint=''){const val=state.profile[key];return `<div class="field"><label for="f-${key}">${label}</label>${type==='money'?`<div class="currency-input"><span>Rp</span><input id="f-${key}" name="${key}" type="number" min="0" max="1000000000000" step="1000" value="${val}" inputmode="numeric" required></div>`:`<input id="f-${key}" name="${key}" type="number" min="${key==='age'?18:0}" max="${key==='age'?100:600}" step="1" value="${val}" required>`}${hint?`<small>${hint}</small>`:''}</div>`;}
function finderView(){const p=state.profile,h=E.health(p);return `${heading('Temukan arah pembiayaanmu.','Ceritakan kebutuhanmu. Kami bantu petakan pilihan yang masuk akal.',button('Muat contoh '+icon('refresh','sm'),'load-demo','secondary'))}<div class="tabs mb" style="max-width:460px"><button class="${p.category==='pribadi'?'active':''}" data-action="switch-profile" data-value="pribadi">${icon('briefcase','sm')} Karyawan / pribadi</button><button class="${p.category==='umkm'?'active':''}" data-action="switch-profile" data-value="umkm">${icon('building','sm')} Pemilik UMKM</button></div><div class="finder-layout"><form id="finder-form" novalidate>${state.formError?`<div class="form-error" role="alert">${esc(state.formError)}</div>`:''}<section class="form-section"><div class="form-title"><span class="step-number">01</span><h3>Kebutuhan pembiayaan</h3></div><div class="fields">${field('amount','Berapa dana yang dibutuhkan?')}${field('maxInstallment','Batas cicilan yang nyaman','money','Batas pilihanmu; tetap diperiksa dengan kapasitas kas.')}<div class="field"><label for="f-tenor">Tenor pinjaman</label><select id="f-tenor" name="tenor">${[6,12,18,24,36,48,60,84,120,180].map(n=>`<option value="${n}" ${p.tenor===n?'selected':''}>${n} bulan${n>=12?' · '+number(n/12)+' tahun':''}</option>`).join('')}</select></div><div class="field"><label for="f-purpose">Tujuan pembiayaan</label><select id="f-purpose" name="purpose">${(p.category==='umkm'?[['modal','Modal kerja'],['investasi','Investasi usaha']]:[['pribadi','Kebutuhan pribadi'],['renovasi','Renovasi rumah'],['pendidikan','Biaya pendidikan']]).map(([v,l])=>`<option value="${v}" ${p.purpose===v?'selected':''}>${l}</option>`).join('')}</select></div></div></section><section class="form-section"><div class="form-title"><span class="step-number">02</span><h3>${p.category==='pribadi'?'Gambaran keuangan bulanan':'Arus kas usaha bulanan'}</h3></div><div class="fields">${p.category==='pribadi'?field('income','Penghasilan bersih')+field('expenses','Pengeluaran rutin')+field('debt','Cicilan berjalan')+field('other','Kewajiban rutin lainnya'):field('revenue','Omzet usaha','money','Pendapatan kotor; bukan kemampuan bayar.')+field('variableCost','Biaya variabel','money','Bahan baku / biaya yang berubah bersama omzet.')+field('fixedCost','Biaya tetap','money','Sewa, gaji tetap, dan biaya tetap lainnya.')+field('ownerDraw','Penarikan pemilik','money','Kebutuhan rumah tangga dari kas usaha.')+field('debt','Cicilan usaha berjalan')+field('businessMonths','Umur usaha (bulan)','number')}${field('reserve','Alokasi cadangan per bulan')}${field('emergency','Saldo dana darurat','money','Saldo tersimpan, terpisah dari alokasi cadangan bulanan.')}</div></section><section class="form-section"><div class="form-title"><span class="step-number">03</span><h3>Informasi dasar</h3></div><div class="fields">${field('age','Usia pemohon','number')}<div class="field"><label for="f-collateral">Ketersediaan agunan tambahan</label><select id="f-collateral" name="collateral"><option value="no" ${p.collateral==='no'?'selected':''}>Tidak tersedia</option><option value="yes" ${p.collateral==='yes'?'selected':''}>Tersedia · perlu penilaian bank</option></select></div></div>${p.category==='pribadi'?`<label class="check-line mt"><input type="checkbox" name="bcaMember" ${p.bcaMember?'checked':''}>Profil demo: payroll BCA atau kartu kredit BCA aktif ≥1 tahun, serta karyawan tetap ≥1 tahun.</label>`:''}<div class="hint mt">${icon('shield','sm')} Gunakan data fiktif untuk demonstrasi. Kami tidak meminta NIK, OTP, PIN, atau akses rekening.</div></section><button type="submit" class="btn full">Cari pembiayaan yang relevan ${icon('arrow','sm')}</button><p class="disclaimer">Hasil adalah simulasi berdasarkan katalog manual. Persyaratan serta keputusan akhir ditentukan bank.</p></form><aside class="sticky-panel"><div class="summary-main"><div class="eyebrow" style="color:#a4c2b4">RINGKASAN RENCANAMU</div><div class="summary-amount" id="live-amount">${rupiah(p.amount)}</div><div class="summary-row"><span class="muted">Jangka waktu</span><strong id="live-tenor">${p.tenor} bulan</strong></div><div class="summary-row"><span class="muted">Kas setelah kewajiban & cadangan</span><strong id="live-cash">${rupiah(h.available)}</strong></div><div class="summary-row"><span class="muted">Kapasitas angsuran model</span><strong id="live-capacity">${rupiah(h.capacity)}</strong></div><p class="disclaimer" style="color:#a9c2bb">${p.category==='pribadi'?'Model: nilai terkecil antara sisa kas, batas pilihanmu, dan 35% gaji bersih dikurangi cicilan lama.':'Model: nilai terkecil antara sisa kas, batas pilihanmu, dan arus kas sebelum utang ÷ 1,25 dikurangi utang lama.'}</p></div><div class="panel mt"><h3 style="font-size:13px">Bagaimana kami mencocokkan?</h3>${[['01','Saring nominal, tenor, dan syarat dasar'],['02','Uji angsuran terhadap kapasitas kas'],['03','Tampilkan alasan serta data yang kurang']].map(([n,t])=>`<div class="row" style="margin-top:19px;align-items:flex-start"><span class="step-number">${n}</span><p style="font-size:11px;flex:1">${t}</p></div>`).join('')}<button class="btn link mt" style="font-size:11px" data-route="sources">Pelajari metodologi ${icon('arrow','sm')}</button>${p.category==='umkm'?`<button class="btn full mt" data-route="funding">Bandingkan bank vs crowdfunding ${icon('arrow','sm')}</button>`:''}</div></aside></div>`;}
function updateForm(form){const data=new FormData(form);for(const [k,v] of data){if(k==='bcaMember')continue;state.profile[k]=['purpose','collateral'].includes(k)?v:Number(v);}if(state.profile.category==='pribadi')state.profile.bcaMember=data.has('bcaMember');const h=E.health(state.profile);if($('#live-capacity')){$('#live-capacity').textContent=rupiah(h.capacity);$('#live-cash').textContent=rupiah(h.available);$('#live-amount').textContent=rupiah(state.profile.amount);$('#live-tenor').textContent=state.profile.tenor+' bulan';}}
function validateProfile(){const p=state.profile;const numeric=['amount','tenor','maxInstallment','income','expenses','debt','other','reserve','emergency','age','revenue','fixedCost','variableCost','ownerDraw','businessMonths'];if(numeric.some(k=>!Number.isFinite(p[k])||p[k]<0||p[k]>1e12))return 'Masukkan angka valid yang tidak negatif pada semua kolom.';if(p.amount<100000||p.amount>1e10)return 'Nominal pinjaman harus antara Rp100.000 dan Rp10 miliar untuk simulasi ini.';if(p.tenor<1||p.tenor>180||!Number.isInteger(p.tenor))return 'Tenor harus bilangan bulat 1–180 bulan.';if(p.age<18||p.age>100)return 'Usia pemohon untuk simulasi harus 18–100 tahun.';if((p.category==='pribadi'?p.income:p.revenue)<=0)return 'Penghasilan atau omzet harus lebih dari nol.';return '';}
function resultsView(){let matches=listMatches(),eligible=matches.filter(m=>m.status!=='no'),fit=matches.filter(m=>m.status==='fit').length;const sort=(a,b)=>state.sort==='installment'?(a.cost.installment??Infinity)-(b.cost.installment??Infinity):state.sort==='knowncost'?(a.cost.knownTotal??Infinity)-(b.cost.knownTotal??Infinity):({fit:0,confirm:1,no:2}[a.status]-{fit:0,confirm:1,no:2}[b.status]);let show=matches.filter(m=>state.resultsFilter==='all'||m.status===state.resultsFilter).sort(sort);
 return `${heading('Pilihan yang lebih terarah.',`${state.profile.category==='pribadi'?'Kredit pribadi':'Pembiayaan UMKM'} · ${rupiah(state.profile.amount)} · ${state.profile.tenor} bulan`,button('Ubah kebutuhan '+icon('refresh','sm'),'edit-finder','secondary'))}<div class="metric-grid"><div class="metric green"><small>Kapasitas angsuran model</small><strong>${rupiah(E.health(state.profile).capacity)}</strong><span>per bulan · berdasarkan profil yang kamu masukkan</span></div><div class="metric"><small>Sesuai parameter simulasi</small><strong>${fit} produk</strong><span>Bukan persetujuan atau probabilitas kredit</span></div><div class="metric"><small>Relevan, perlu konfirmasi</small><strong>${eligible.length-fit} produk</strong><span>Data atau persyaratan belum lengkap</span></div></div>${state.profile.category==='umkm'?fundingPromoView():''}${eligible.length===0?emptyResults(matches):`<div class="hint mb">${icon('info','sm')} Angka cicilan adalah estimasi bersyarat. Produk tidak diberi peringkat berdasarkan komisi. Total biaya diketahui bukan total final.</div>`}<div class="result-toolbar"><div class="row wrap">${[['all','Semua'],['fit','Sesuai parameter'],['confirm','Perlu konfirmasi'],['no','Di luar parameter']].map(([v,l])=>`<button class="pill ${state.resultsFilter===v?'active':''}" data-action="result-filter" data-value="${v}">${l}</button>`).join('')}</div><select class="pill" id="results-sort" aria-label="Urutkan hasil"><option value="relevant">Urutkan: relevansi</option><option value="installment" ${state.sort==='installment'?'selected':''}>Cicilan estimasi</option><option value="knowncost" ${state.sort==='knowncost'?'selected':''}>Biaya diketahui</option></select></div>${show.length?`<div class="product-grid">${show.map(m=>productCard(m.product,true)).join('')}</div>`:'<div class="empty"><h2>Tidak ada produk pada filter ini.</h2><p>Pilih filter lain untuk melihat alasan dan alternatif.</p></div>'}<p class="disclaimer">Diperiksa 7 November 2026. Nilai "mulai" dapat berubah sesuai segmen, tarif saat akad, dan evaluasi bank. Biaya yang tidak tersedia tidak dihitung sebagai nol.</p>`;}
function emptyResults(matches){const alternatives=matches.map(m=>E.alternative(m.product,state.profile)).filter(Boolean).sort((a,b)=>b.amount-a.amount).slice(0,2);return `<div class="empty mb">${icon('target')}<h2>Belum ada yang sesuai saat ini.</h2><p>Kami tidak memaksakan rekomendasi. Kebutuhan, tenor, atau kapasitas angsuranmu berada di luar parameter produk.</p>${alternatives.length?alternatives.map(a=>`<div class="hint" style="text-align:left;max-width:550px;margin:12px auto"><div><strong>Alternatif ${esc(a.product.bank)}: ${rupiah(a.amount)}</strong><p style="margin:5px 0;font-size:11px">Pada tenor ${a.tenor} bulan, estimasi angsuran ${rupiah(a.installment)}. Asumsi bunga ${number(a.rate)}% per tahun, metode ${a.product.method}; biaya tambahan belum lengkap. Penyangga model 5%.</p>${button('Coba nominal ini','apply-alternative','soft small',`data-amount="${a.amount}"`)}</div></div>`).join(''):`<p>Belum ada alternatif nominal yang lolos batas dasar. Tinjau arus kas, kurangi kewajiban, atau tunda pengajuan.</p>`}${button('Tinjau kemampuan bayar','go-analysis','secondary')}</div>`;}

function fundingPromoView(){return `<section class="funding-promo mt"><div><span class="tag green">KHUSUS UMKM · FITUR BARU</span><h2>Bank atau crowdfunding?</h2><p>Bandingkan jalur pendanaan berdasarkan arus kas, kesiapan usaha, dan konsekuensi kepemilikan.</p></div><button class="btn" data-route="funding">Analisis sumber pendanaan ${icon('arrow','sm')}</button></section>`;}
function fundingSelect(key,label,options,hint=''){return `<div class="field"><label for="fund-${key}">${label}</label><select id="fund-${key}" data-funding="${key}">${options.map(([v,l])=>`<option value="${v}" ${state.funding[key]===v?'selected':''}>${l}</option>`).join('')}</select>${hint?`<small>${hint}</small>`:''}</div>`;}
function fundingView(){
 if(state.profile.category!=='umkm')return `${heading('Pilih jalur pendanaan yang tepat.','Analisis bank dan Securities Crowdfunding dirancang untuk kebutuhan usaha.') }<section class="panel funding-intro"><span class="tag navy">FITUR ANALISIS UMKM</span><h2 style="margin-top:12px">Crowdfunding ditujukan untuk usaha, bukan kredit pribadi.</h2><p class="muted small mt">Ganti profil ke UMKM agar ModalMatch dapat menganalisis kebutuhan modal, arus kas usaha, kesiapan SCF, dan simulasi struktur kepemilikan.</p>${button('Gunakan contoh profil UMKM '+icon('arrow','sm'),'use-umkm-demo','mt')}</section>`;
 const p=state.profile,analysis=E.fundingMatch(PRODUCTS,p,state.funding),dilution=E.equityDilution(Number(state.funding.preMoney),Number(state.funding.raiseAmount)),bankLabel={fit:'Sesuai parameter',confirm:'Perlu konfirmasi',no:'Belum ada yang sesuai'}[analysis.bank.status],bankClassName={fit:'fit',confirm:'confirm',no:'no'}[analysis.bank.status],scfLabel={ready:'Siap dieksplorasi',prepare:'Perlu persiapan',notready:'Belum siap',notfit:'Tidak cocok untuk SCF saham'}[analysis.scf.status],scfClassName={ready:'fit',prepare:'confirm',notready:'no',notfit:'no'}[analysis.scf.status];
 const best=analysis.bank.candidates.slice().sort((a,b)=>(a.cost.installment??Infinity)-(b.cost.installment??Infinity)).slice(0,3);
 const reason=analysis.scf.criteria.map(c=>`<div class="readiness-row"><span>${esc(c.label)}</span><span class="readiness-points ${c.points[c.value]===20?'good':c.points[c.value]===10?'mid':'bad'}">${c.points[c.value]??0}/20</span></div>`).join('');
 const scoreColor=analysis.scf.status==='ready'?'var(--emerald)':analysis.scf.status==='prepare'?'var(--amber)':'var(--red)';
 const recommendedBank=analysis.level==='bank',recommendedScf=analysis.level==='scf',both=analysis.level==='both';
 return `${heading('Temukan sumber pendanaan yang sesuai.','ModalMatch menilai dua jalur berdasarkan kebutuhan modal, kemampuan kas, dan kesiapan usaha.',button('Ubah profil UMKM '+icon('refresh','sm'),'edit-finder','secondary'))}
 <div class="funding-context"><div><span class="eyebrow">KEBUTUHAN MODAL</span><strong>${rupiah(p.amount)}</strong><small>${p.purpose==='investasi'?'Investasi usaha':'Modal kerja'} · ${p.businessMonths} bulan usia usaha</small></div><div><span class="eyebrow">KAPASITAS ANGSURAN MODEL</span><strong>${rupiah(analysis.health.capacity)}</strong><small>Per bulan · bukan penilaian bank</small></div><div><span class="eyebrow">ARUS KAS SETELAH KEWAJIBAN</span><strong>${rupiah(analysis.health.available)}</strong><small>Setelah biaya, utang dan cadangan</small></div></div>
 <section class="funding-recommendation ${analysis.level==='none'?'neutral':analysis.level==='bank-confirm'?'amber':''}">
 <div class="row between wrap"><span class="eyebrow">HASIL SMART FUNDING MATCH</span><span class="tag ${analysis.level==='none'?'outline':analysis.level==='bank-confirm'?'amber':'green'}">${analysis.level==='both'?'DUA ALTERNATIF':analysis.level==='none'?'BELUM ADA KECocokan'.toUpperCase():'HASIL SIMULASI'}</span></div>
 <h2>${esc(analysis.recommendation)}</h2><p>${esc(analysis.detail)}</p>
 <small>Hasil dihitung dari input profil, katalog kredit lokal, dan checklist kesiapan SCF. Ini bukan persetujuan bank, penerimaan penerbit, atau rekomendasi investasi.</small>
 </section>
 <div class="funding-result-grid">
  <section class="funding-card ${bankClassName} ${recommendedBank?'recommended':''}">
   <div class="row between"><span class="funding-icon">${icon('building')}</span><span class="tag ${analysis.bank.status==='fit'?'green':analysis.bank.status==='confirm'?'amber':'red'}">${bankLabel}</span></div>
   <h2>Kredit Bank / KUR</h2><p class="muted small">Pendanaan berbentuk pinjaman dengan kewajiban pembayaran sesuai kontrak.</p>
   ${best.length?`<div class="funding-candidates">${best.map(m=>`<div class="funding-candidate"><div><strong>${esc(m.product.bank)} · ${esc(m.product.name)}</strong><small>${m.cost.installment===null?'Angsuran belum dapat dihitung':rupiah(m.cost.installment)+' / bulan'}</small></div><span class="tag ${m.status==='fit'?'green':m.status==='no'?'red':'amber'}">${m.status==='fit'?'Sesuai':m.status==='no'?'Tidak sesuai':'Konfirmasi'}</span></div>`).join('')}</div>`:`<div class="funding-empty">Belum ada produk bank yang lolos parameter saat ini. Coba ubah nominal, tenor, agunan, atau kemampuan angsuran.</div>`}
   <ul class="funding-bullets"><li>Mempertahankan kepemilikan usaha.</li><li>Memiliki cicilan dan biaya pinjaman.</li><li>Persetujuan tetap melalui bank.</li></ul>
   ${button('Lihat katalog kredit UMKM '+icon('arrow','sm'),'funding-bank-catalog','secondary full')}
  </section>
  <section class="funding-card ${scfClassName} ${recommendedScf?'recommended':''}">
   <div class="row between"><span class="funding-icon">${icon('users')}</span><span class="tag ${analysis.scf.status==='ready'?'green':analysis.scf.status==='prepare'?'amber':'red'}">${scfLabel}</span></div>
   <h2>SCF Saham (Equity)</h2><p class="muted small">Pendanaan melalui penawaran saham kepada investor. Pemilik berbagi kepemilikan dan hak sesuai dokumen penawaran.</p>
   <div class="scf-score"><div><strong>${analysis.scf.score}</strong><small>/ 100 indikator kesiapan</small></div><div class="scf-progress"><span style="width:${analysis.scf.score}%;background:${scoreColor}"></span></div></div>
   <div class="readiness-list">${reason}</div>
   <ul class="funding-bullets"><li>Tidak memakai cicilan pinjaman bulanan seperti kredit biasa.</li><li>Kepemilikan terdilusi dan investor memiliki hak sesuai efek.</li><li>Proses dan kelayakan ditentukan penyelenggara berizin serta ketentuan SCF.</li></ul>
  </section>
 </div>
 <section class="panel mt"><div class="panel-head"><div><h2>Uji kesiapan usaha untuk SCF saham</h2><p>Jawaban awal adalah contoh demo. Ubah sesuai kondisi usaha; warna dan rekomendasi di atas akan diperbarui otomatis.</p></div><span class="tag outline">Checklist simulasi</span></div>
 <div class="funding-form-grid">
 ${fundingSelect('legal','1. Legalitas usaha',[['complete','Lengkap'],['partial','Sebagian tersedia'],['none','Belum tersedia']])}
 ${fundingSelect('records','2. Pencatatan keuangan',[['monthly','Rutin dan terdokumentasi'],['basic','Masih sederhana'],['none','Belum tersedia']])}
 ${fundingSelect('plan','3. Rencana bisnis dan penggunaan dana',[['yes','Sudah disusun'],['partial','Masih perlu diperkuat'],['no','Belum disusun']])}
 ${fundingSelect('equity','4. Kesediaan berbagi kepemilikan',[['yes','Bersedia mempertimbangkan saham'],['consider','Masih mempertimbangkan'],['no','Tidak bersedia berbagi kepemilikan']],'Jika tidak bersedia berbagi saham, SCF saham tidak cocok. Efek utang/sukuk tidak dihitung pada prototipe ini.')}
 ${fundingSelect('disclosure','5. Kesiapan keterbukaan informasi',[['yes','Siap membuka informasi dan pelaporan usaha'],['partial','Perlu persiapan'],['no','Belum siap']])}
 </div><div class="hint mt">${icon('info','sm')} Skor 0–100 adalah checklist internal prototipe, bukan skor OJK, standar kelulusan penyelenggara, atau jaminan kampanye diterima.</div>
 </section>
 <section class="panel mt"><div class="panel-head"><div><h2>Simulasi dilusi kepemilikan saham</h2><p>Hitung estimasi porsi investor jika usaha menerbitkan saham baru.</p></div><span class="tag navy">Finance simulator</span></div>
 <div class="funding-form-grid">
  <div class="field"><label for="fund-preMoney">Valuasi sebelum pendanaan (pre-money)</label><div class="currency-input"><span>Rp</span><input id="fund-preMoney" type="number" min="1" step="1000000" data-funding-number="preMoney" value="${Number(state.funding.preMoney)||0}"></div></div>
  <div class="field"><label for="fund-raiseAmount">Target dana melalui saham</label><div class="currency-input"><span>Rp</span><input id="fund-raiseAmount" type="number" min="1" step="1000000" data-funding-number="raiseAmount" value="${Number(state.funding.raiseAmount)||0}"></div><small>Default mengikuti contoh UMKM; sesuaikan dengan kebutuhan pendanaan.</small></div>
 </div>
 <div class="row wrap mt"><button class="btn secondary small" data-action="funding-sync-amount">Samakan dengan kebutuhan dana ${icon('refresh','sm')}</button></div>
 ${dilution?`<div class="dilution-result"><div class="row between"><div><small>Estimasi kepemilikan investor baru</small><strong>${number(dilution.investorPct)}%</strong></div><div class="align-right"><small>Kepemilikan pemilik lama</small><strong>${number(dilution.existingPct)}%</strong></div></div><div class="dilution-bar"><span style="width:${dilution.existingPct}%"></span><i style="width:${dilution.investorPct}%"></i></div><div class="detail-grid"><div class="detail-box"><small>Valuasi pre-money</small><strong>${rupiah(dilution.preMoney)}</strong></div><div class="detail-box"><small>Valuasi post-money</small><strong>${rupiah(dilution.postMoney)}</strong></div></div><p class="disclaimer">Rumus ilustrasi: dana dihimpun ÷ (valuasi pre-money + dana dihimpun). Nilai sebenarnya bergantung pada valuasi, struktur efek, harga penawaran, dan dokumen final. Tidak termasuk biaya penawaran atau hak khusus.</p></div>`:`<div class="hint amber mt">Masukkan valuasi sebelum pendanaan dan target dana yang lebih besar dari nol.</div>`}
 </section>
 <section class="panel mt"><div class="panel-head"><div><h2>Perbandingan karakter pendanaan</h2><p>Jangan membandingkan bunga pinjaman dengan persentase saham secara langsung.</p></div></div>
 <div class="data-table-wrap"><table class="data-table funding-compare"><thead><tr><th>Aspek</th><th>Kredit Bank / KUR</th><th>SCF Saham</th></tr></thead><tbody>
 <tr><td>Sumber dana</td><td>Bank</td><td>Investor melalui penyelenggara SCF</td></tr>
 <tr><td>Kewajiban rutin</td><td>Angsuran sesuai kontrak</td><td>Tidak ada cicilan pinjaman bulanan; hak investor mengikuti efek dan dokumen</td></tr>
 <tr><td>Kepemilikan usaha</td><td>Tidak terdilusi karena pinjaman</td><td>Terdilusi melalui penerbitan saham baru</td></tr>
 <tr><td>Konsekuensi finansial</td><td>Bunga/margin dan biaya pinjaman</td><td>Berbagi kepemilikan, hak ekonomi, dan kemungkinan hak suara</td></tr>
 <tr><td>Risiko utama</td><td>Tekanan arus kas dan risiko gagal bayar</td><td>Dilusi, keterbukaan informasi, dan tanggung jawab kepada pemegang saham</td></tr>
 <tr><td>Penilaian akhir</td><td>Bank menilai permohonan</td><td>Penyelenggara menilai penerbit dan proses penawaran</td></tr>
 </tbody></table></div>
 <p class="disclaimer mt">SCF juga dapat menawarkan efek bersifat utang dan sukuk. Prototipe ini hanya mensimulasikan SCF saham agar kalkulator dilusi relevan. Efek utang/sukuk mempunyai kewajiban dan perhitungan berbeda.</p>
 </section>
 <section class="panel mt"><div class="panel-head"><div><h2>Verifikasi penyelenggara dan aturan SCF</h2><p>Jangan memilih platform hanya berdasarkan promosi atau tampilan aplikasi.</p></div><span class="tag amber">Perlu verifikasi terbaru</span></div>
 <p class="small muted">ModalMatch tidak menjadi penyelenggara crowdfunding. Sebelum melanjutkan, periksa identitas dan status izin penyelenggara melalui kanal resmi OJK serta baca dokumen penawaran, risiko, biaya, hak investor, dan mekanisme pengembalian/exit.</p>
 <div class="row wrap mt"><a class="btn secondary small" href="https://find.ojk.go.id/Home" target="_blank" rel="noopener">Direktori FIND OJK ${icon('external','sm')}</a><a class="btn secondary small" href="https://ojk.go.id/id/regulasi/Pages/POJK-17-Tahun-2025-Penawaran-Efek-Melalui-Layanan-Urun-Dana-Berbasis-Teknologi-Informasi.aspx" target="_blank" rel="noopener">POJK 17/2025 ${icon('external','sm')}</a></div>
 </section>
 <p class="disclaimer mt">Warna hijau berarti indikator internal prototipe terpenuhi untuk dieksplorasi, bukan persetujuan bank, izin OJK, rekomendasi investasi, jaminan dana terkumpul, atau jaminan usaha berhasil. Data demo diproses di perangkat ini.</p>`;
}

function catalogView(){let items=PRODUCTS.filter(p=>(state.category==='archive'?!p.active:p.active)&&(state.category==='all'||state.category==='archive'||p.category===state.category)&&(state.bank==='all'||p.bank===state.bank)&&(!state.search||(p.bank+' '+p.name+' '+p.category).toLowerCase().includes(state.search.toLowerCase()))&&(!state.filterAmount||((p.minAmount==null||state.filterAmount>=p.minAmount)&&(p.maxAmount==null||state.filterAmount<=p.maxAmount)))&&(!state.filterTenor||((p.minTenor==null||state.filterTenor>=p.minTenor)&&(p.maxTenor==null||state.filterTenor<=p.maxTenor)&&(!p.allowedTenors||p.allowedTenors.includes(state.filterTenor)))));if(state.sort==='bank')items.sort((a,b)=>a.bank.localeCompare(b.bank));if(state.sort==='limit')items.sort((a,b)=>(b.maxAmount||0)-(a.maxAmount||0));
return `${heading('Satu katalog. Banyak pilihan.','19 produk aktif · 9 bank aktif · 1 bank dalam arsip · Data diperiksa 7 Nov 2026',button('Sumber & data '+icon('external','sm'),'go-sources','secondary'))}<div class="filterbar"><input id="catalog-search" aria-label="Cari katalog" value="${esc(state.search)}" placeholder="Cari bank atau produk pembiayaan…"><select id="bank-filter" aria-label="Filter bank"><option value="all">Semua bank</option>${[...new Set(PRODUCTS.map(p=>p.bank))].map(b=>`<option ${state.bank===b?'selected':''}>${esc(b)}</option>`).join('')}</select><select id="catalog-sort" aria-label="Urutkan katalog"><option value="relevant">Pilihan katalog</option><option value="bank" ${state.sort==='bank'?'selected':''}>Nama bank A–Z</option><option value="limit" ${state.sort==='limit'?'selected':''}>Plafon tertinggi</option></select><input style="flex:0 1 150px;min-width:130px" id="amount-filter" type="number" min="0" placeholder="Nominal (Rp)" aria-label="Filter nominal" value="${state.filterAmount||''}"><select id="tenor-filter" aria-label="Filter tenor"><option value="0">Semua tenor</option>${[12,24,36,48,60].map(n=>`<option value="${n}" ${state.filterTenor===n?'selected':''}>${n} bulan</option>`).join('')}</select></div><div class="result-toolbar"><div class="row wrap">${[['all','Semua produk'],['pribadi','Kredit pribadi'],['umkm','Pembiayaan UMKM'],['archive','Arsip produk']].map(([v,l])=>`<button class="pill ${state.category===v?'active':''}" data-action="catalog-category" data-value="${v}">${l}</button>`).join('')}</div><span class="small muted">${items.length} produk ditemukan</span></div>${items.length?`<div class="product-grid">${items.map(p=>productCard(p)).join('')}</div>`:`<div class="empty">${icon('search')}<h2>Belum menemukan produk?</h2><p>Coba kata kunci lain atau hapus filter.</p>${button('Reset filter','reset-filters','secondary')}</div>`}<p class="disclaimer">Filter rentang menyertakan produk dengan batas yang belum dipublikasikan; detailnya ditandai perlu konfirmasi. Arsip tidak disertakan dalam pencarian aktif. Minimum bunga bukan tarif pasti; produk dengan biaya tidak lengkap tidak dinyatakan termurah.</p>`;}

function compareView(){const items=state.compare.map(id=>PRODUCTS.find(p=>p.id===id)).filter(Boolean);if(items.length<2)return `${heading('Lihat perbedaannya dengan jelas.','Bandingkan 2–3 produk menggunakan nominal dan tenor yang sama.')}<div class="empty">${icon('compare')}<h2>${items.length?'Tambahkan satu produk lagi.':'Belum ada produk untuk dibandingkan.'}</h2><p>Pilih kotak “Bandingkan” pada kartu produk. Semua estimasi menggunakan satu profil yang sama.</p><button class="btn" data-route="catalog">Jelajahi katalog ${icon('arrow','sm')}</button></div>`;
 const costs=items.map(p=>E.cost(p,state.profile.amount,state.profile.tenor));const row=(name,fn)=>`<tr><td>${name}</td>${items.map((p,i)=>`<td>${fn(p,costs[i],i)}</td>`).join('')}</tr>`;
 return `${heading('Bandingkan sebelum memutuskan.','Transparansi biaya, bukan sekadar bunga terendah.',button('Ubah parameter','edit-finder','secondary'))}<div class="hint mb">${icon('info','sm')} Simulasi ${rupiah(state.profile.amount)} selama ${state.profile.tenor} bulan. Metode, tarif bersyarat, dan cakupan biaya dapat berbeda. Urutan kolom mengikuti pilihanmu.</div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>PARAMETER</th>${items.map(p=>`<th><div class="row">${bankLogo(p)}<div><strong>${esc(p.name)}</strong><div class="tiny muted">${esc(p.bank)}</div></div></div><button class="btn link tiny mt" data-action="remove-compare" data-id="${p.id}">Hapus produk ×</button></th>`).join('')}</tr></thead><tbody>${row('Status parameter',p=>statusTag(E.match(p,state.profile)))}${row('Estimasi angsuran',(_,c)=>c.installment===null?'Perlu konfirmasi':`<strong style="font-size:19px">${rupiah(c.installment)}</strong><div class="tiny muted">per bulan${_.monthlyFee?' + biaya bulanan '+rupiah(_.monthlyFee):''}</div>`)}${row('Bunga & metode',(p,c)=>`${esc(p.rateText)}<div class="tiny muted">${c.method==='flat'?(p.indicativeFlat?'Ilustrasi setara flat; kontrak dapat anuitas':'Flat, pokok awal'):c.method==='annuity'?'Model anuitas bulanan':'Metode belum terverifikasi'}</div>`)}${row('Total angsuran',(_,c)=>c.total===null?'Tidak dapat dihitung':rupiah(c.total))}${row('Total bunga ilustrasi',(_,c)=>c.interest===null?'Tidak dapat dihitung':rupiah(c.interest))}${row('Biaya awal diketahui',(_,c)=>c.knownFeeCount?`${rupiah(c.knownFee)}<div class="tiny muted">Belum termasuk biaya yang tidak diketahui</div>`:'Belum diketahui')}${row('Cara bayar biaya',p=>p.feeTreatment==='deducted'?'Biaya diketahui dipotong pencairan':p.feeTreatment==='separate'?'Dibayar terpisah':'Cara potong perlu konfirmasi')}${row('Dana diterima setelah biaya diketahui',(_,c)=>c.net===null?'Perlu konfirmasi cara potong':`${rupiah(c.net)}<div class="tiny muted">Dapat berkurang oleh potongan lain</div>`)}${row('Angsuran + biaya diketahui',(_,c)=>c.knownTotal===null?'Tidak dapat dihitung':`<strong>${rupiah(c.knownTotal)}</strong><div class="tiny muted">Bukan biaya keseluruhan final</div>`)}${row('Biaya efektif tahunan',(_,c)=>c.effectiveAnnual===null?'Belum dapat ditetapkan: biaya tidak lengkap':number(c.effectiveAnnual)+'%')}${row('Batas plafon',p=>`${p.minAmount?'Rp'+short(p.minAmount):'Minimum konfirmasi'} – ${p.maxAmount?'Rp'+short(p.maxAmount):'maksimum konfirmasi'}`)}${row('Agunan',p=>esc(p.collateral))}${row('Syarat penting',p=>esc(p.requirements.slice(0,2).join('; ')))}${row('Keterbatasan',p=>`<span class="tiny">${esc(p.rateConditions)}</span>`)}${row('Tindak lanjut',p=>button('Detail biaya','detail','secondary small',`data-id="${p.id}"`)+` <button class="btn small mt" data-action="bank-referral" data-id="${p.id}">Lanjut ke bank ${icon('external','sm')}</button>`)}</tbody></table></div><p class="disclaimer">Bunga flat dan efektif tidak dibandingkan langsung dari persentase. Nilai yang dapat dihitung disajikan dengan arus kas dan asumsi masing-masing. Produk di luar plafon atau tenor tidak menjadi rekomendasi, walaupun ilustrasi matematis masih ditampilkan.</p>`;}
function analysisView(){const p=state.profile,h=E.health(p),s=E.health(p,state.risk),product=selectedProduct(),c=product?E.cost(product,p.amount,p.tenor):{installment:null},newPay=c.installment??0,remaining=h.available-newPay,stressed=s.available-newPay,afterRatio=p.category==='pribadi'?(h.debt+newPay)/h.incoming:(h.debt+newPay>0?h.beforeDebt/(h.debt+newPay):0);const max=Math.max(h.available,s.available,1);
 return `${heading('Pahami ruang gerak finansialmu.','Uji rencana hari ini terhadap perubahan yang mungkin terjadi.',button('Ubah profil','edit-finder','secondary'))}<div class="metric-grid"><div class="metric green"><small>Kas tersedia sebelum pinjaman baru</small><strong>${rupiah(h.available)}</strong><span>Setelah biaya, utang berjalan, dan cadangan bulanan</span></div><div class="metric"><small>Kapasitas angsuran model</small><strong>${rupiah(h.capacity)}</strong><span>${p.category==='pribadi'?'Model rasio 35%, bukan aturan seluruh bank':'Model DSCR 1,25×, bukan aturan seluruh bank'}</span></div><div class="metric"><small>Kas setelah cicilan baru</small><strong style="color:${remaining<0?'var(--red)':'var(--emerald)'}">${rupiah(remaining)}</strong><span>${product?esc(product.bank+' '+product.name):'Produk belum dipilih'}</span></div></div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Bagaimana jika kondisi berubah?</h2><p>${p.category==='pribadi'?'Penurunan penghasilan dan kenaikan biaya hidup.':'Biaya variabel mengikuti omzet; biaya tetap tetap diperhitungkan.'}</p></div>${icon('chart')}</div><div class="field mb"><label for="risk-product">Produk yang diuji</label><select id="risk-product">${PRODUCTS.filter(x=>x.active&&x.category===p.category&&E.cost(x,p.amount,p.tenor).installment!=null).map(x=>`<option value="${x.id}" ${product?.id===x.id?'selected':''}>${esc(x.bank+' · '+x.name)}</option>`).join('')}</select><small>${product?esc(product.rateConditions):'Tidak ada produk yang dapat dihitung.'}</small></div><div class="fields">${[['incomeDrop',p.category==='pribadi'?'Penghasilan turun':'Omzet turun',0,80,'%'],['costRise',p.category==='pribadi'?'Biaya hidup naik':'Biaya operasional naik',0,80,'%']].map(([k,l,min,max,suffix])=>`<div class="field"><label for="risk-${k}">${l}<strong>${state.risk[k]}${suffix}</strong></label><input id="risk-${k}" data-risk="${k}" type="range" min="${min}" max="${max}" step="5" value="${state.risk[k]}"></div>`).join('')}<div class="field"><label for="risk-extraDebt">Kewajiban tambahan / bulan</label><div class="currency-input"><span>Rp</span><input id="risk-extraDebt" data-risk="extraDebt" type="number" min="0" value="${state.risk.extraDebt}"></div></div><div class="field"><label for="risk-reserveDraw">Dana darurat terpakai</label><div class="currency-input"><span>Rp</span><input id="risk-reserveDraw" data-risk="reserveDraw" type="number" min="0" value="${state.risk.reserveDraw}"></div></div></div><div class="bar-chart" role="img" aria-label="Kas tersedia awal ${rupiah(h.available)}, setelah perubahan ${rupiah(s.available)}"><div class="bar-col"><strong>${rupiah(h.available)}</strong><div class="bar" style="height:${Math.max(4,h.available/max*140)}px"></div><small>Kondisi awal</small></div><div class="bar-col"><strong>${rupiah(s.available)}</strong><div class="bar" style="height:${Math.max(4,s.available/max*140)}px;${s.available<0?'background:var(--red)':''}"></div><small>Setelah skenario</small></div></div><div class="row wrap between"><span class="small muted">Kas tersedia sebelum cicilan baru</span>${button('Reset skenario','reset-risk','secondary small')}</div><div class="hint ${newPay>s.capacity?'red':''} mt">${icon('info','sm')}<div><strong>${newPay>s.capacity?'Rencana mulai tertekan.':'Masih dalam kapasitas skenario.'}</strong><br>Estimasi cicilan ${rupiah(newPay)}; kapasitas setelah skenario ${rupiah(s.capacity)}. Sisa kas setelah cicilan ${rupiah(stressed)}. ${stressed<0?'Terdapat kekurangan dana bulanan.':'Arus kas positif tidak menjamin persetujuan bank.'}</div></div></section><aside class="stack"><section class="panel"><h3>Komposisi arus kas</h3><div class="split-meter">${[[h.expenses,"#a2b5aa"],[h.debt+p.reserve+newPay,"#cbbd8d"],[Math.max(0,remaining),"var(--emerald)"]].map(([v,color])=>`<span style="width:${Math.max(0,v)/Math.max(h.expenses+h.debt+p.reserve+newPay+Math.max(0,remaining),1)*100}%;background:${color}"></span>`).join('')}</div>${[['Pemasukan',h.incoming],['Biaya rutin / usaha + penarikan',h.expenses],['Cicilan lama',h.debt],['Cadangan bulanan',p.reserve],['Cicilan baru (ilustrasi)',newPay],['Sisa kas',remaining]].map(([l,n])=>`<div class="summary-row" style="border-color:var(--line)"><span class="muted">${l}</span><strong>${rupiah(n)}</strong></div>`).join('')}<p class="disclaimer">${p.category==='pribadi'?`Rasio cicilan: ${number(h.ratio*100)}% sebelum → ${number(afterRatio*100)}% setelah pinjaman.`:`DSCR setelah cicilan baru: ${number(afterRatio)}×. Arus kas tersedia untuk utang dibagi total pembayaran utang.`}<br>Dana darurat skenario: ${rupiah(s.reserveBalance)}, setara ${number(Math.round(s.runway*10)/10)} bulan biaya & cicilan lama.</p></section><section class="panel"><h3>Langkah yang bisa dipertimbangkan</h3><p class="small muted mt">${newPay>s.capacity?'Tinjau nominal yang lebih kecil, kurangi kewajiban, atau tunda pinjaman sampai arus kas membaik.':'Pertahankan cadangan dan konfirmasi biaya lengkap sebelum melanjutkan.'}</p>${product?smartAlternative(product,s.capacity):''}<button class="btn soft full mt" data-route="reports">Lihat laporan analisis ${icon('arrow','sm')}</button></section></aside></div><div class="panel mt"><h3>Asumsi yang bisa kamu telusuri</h3><p class="disclaimer">${p.category==='pribadi'?'Kas = penghasilan bersih − pengeluaran − kewajiban lain − cicilan berjalan − cadangan bulanan. Kapasitas = maksimum(0, minimum(kas, 35% × penghasilan − cicilan lama, batas pilihan)).':'Kas = omzet − biaya variabel − biaya tetap − penarikan pemilik − cicilan − cadangan. Pada stress test, biaya variabel turun proporsional dengan omzet, lalu seluruh biaya operasional naik sesuai slider. Kapasitas = maksimum(0, minimum(kas, arus kas sebelum utang ÷ 1,25 − cicilan lama, batas pilihan)).'} Saldo dana darurat tidak dianggap penghasilan bulanan. Angka rasio adalah asumsi perencanaan prototipe; kebijakan bank dapat berbeda.</p></div>`;}
function smartAlternative(product,capacity){const a=E.alternative(product,{...state.profile,maxInstallment:Math.min(state.profile.maxInstallment,capacity)});return a?`<div class="hint mt"><div>Nominal ${rupiah(a.amount)} → estimasi ${rupiah(a.installment)}/bulan selama ${a.tenor} bulan.<br><span class="tiny">Bunga model ${number(a.rate)}%/tahun, ${product.method}; 5% penyangga kapasitas. Biaya lain belum lengkap.</span><br>${button('Uji nominal ini','apply-alternative','link small',`data-amount="${a.amount}"`)}</div></div>`:`<p class="disclaimer">Belum ada alternatif nominal yang lolos batas dasar produk dengan kapasitas ini. Perbaiki arus kas sebelum mencoba kembali.</p>`;}
function reportsView(){return `${heading('Rencanamu, dalam satu laporan.','Ringkasan finansial yang bisa disimpan, dipelajari, dan dibawa saat berkonsultasi.')}<div class="two-col"><section class="premium-hero"><span class="tag" style="background:#ffffff17;color:#d9e9c5">${icon('spark','sm')} LAPORAN MODALMATCH</span><h1>Lebih paham biayanya.<br>Lebih siap melangkah.</h1><p>Rangkum profil, perbandingan produk, dan skenario risiko dalam laporan personal yang bisa kamu cetak.</p><div class="feature-list">${['Ringkasan kondisi finansial','Perbandingan biaya diketahui','Skenario penurunan pendapatan','Alternatif nominal terukur','Sumber dan asumsi transparan','Cetak atau simpan sebagai PDF'].map(t=>`<div>${icon('check','sm')}${t}</div>`).join('')}</div><div class="premium-price">Rp25.000 <small>/ laporan · harga rencana</small></div>${button('Buat laporan '+icon('arrow','sm'),'checkout','', 'style="background:#d5edba;color:#23413a"')}<p class="tiny" style="color:#a4bfb5;margin-top:16px">Checkout dan pembayaran pada prototipe hanya simulasi. Tidak ada uang yang ditagihkan.</p></section><section class="report-preview"><div class="row between"><span class="eyebrow muted">PREVIEW LAPORAN</span>${icon('report')}</div><h3 style="font-size:19px;margin-top:22px">Ringkasan finansial ${esc(currentUserName())}</h3><p class="small muted" style="margin:7px 0 18px">${state.profile.category==='pribadi'?'Karyawan':'UMKM'} · ${rupiah(state.profile.amount)}</p><div class="summary-row" style="border-color:var(--line)"><span class="muted">Kapasitas model</span><strong>${rupiah(E.health(state.profile).capacity)}</strong></div><div class="summary-row" style="border-color:var(--line)"><span class="muted">Tenor simulasi</span><strong>${state.profile.tenor} bulan</strong></div><div class="line"></div><div class="line short"></div><div class="report-lock">${icon('lock')}<p class="small muted" style="margin:12px 0">Laporan lengkap tersusun setelah<br>transaksi demo berhasil.</p><button class="btn link" data-action="report-preview">Lihat contoh isi ${icon('arrow','sm')}</button></div></section></div><div class="hint mt">${icon('shield','sm')} Informasi biaya utama, perbandingan dasar, dan peringatan risiko tetap gratis. Biaya Rp25.000 dikenakan pada laporan terstruktur sesuai rencana bisnis.</div><section class="panel mt"><div class="panel-head"><div><h2>Laporan milikmu</h2><p>Setiap laporan menyimpan kondisi saat pembelian demo.</p></div><span class="tag">${state.reports.length} laporan</span></div>${state.reports.length?state.reports.map(r=>`<div class="history-row"><span class="stat-icon">${icon('report')}</span><div><p>Analisis ${r.profile.category==='pribadi'?'pribadi':'usaha'} · ${rupiah(r.profile.amount)}</p><small>${formatDate(r.date)} · ${r.id} · ${r.method}</small></div><button class="btn soft small" data-action="open-report" data-id="${r.id}">Buka laporan</button></div>`).join(''):`<div class="empty" style="padding:30px;border:0"><p style="margin:0 auto">Belum ada laporan. Lengkapi profil dan jalankan analisis terlebih dahulu.</p></div>`}</section>`;}
function profileView(){const auth=state.auth||{},name=currentUserName(),email=auth.email||'Tidak menggunakan email',mode=auth.type==='guest'?'Mode tamu':'Akun demo lokal';return `${heading('Profil dan aktivitasmu.','Kelola akun demo, produk tersimpan, serta aktivitas yang dilakukan di browser ini.')}<div class="two-col"><div class="stack"><section class="panel"><div class="profile-card"><span class="avatar">${userInitials()}</span><div><h2>${esc(name)}</h2><p class="small muted">${esc(email)} · ${mode}</p><span class="tag green mt">Tersimpan di browser ini</span></div><button class="btn secondary small" style="margin-left:auto" data-route="finder">Ubah profil keuangan</button></div><div class="hint mt">${icon('info','sm')} Nama akun hanya untuk personalisasi aplikasi. Profil keuangan di bawah menu Cari Pembiayaan dapat diubah secara terpisah.</div></section><section class="panel"><div class="panel-head"><h2>Produk tersimpan</h2><span class="tag">${state.saved.length}</span></div>${state.saved.length?state.saved.map(id=>PRODUCTS.find(p=>p.id===id)).filter(Boolean).map(p=>`<div class="history-row">${bankLogo(p)}<div><p>${esc(p.name)}</p><small>${esc(p.bank)} · ${p.category}</small></div><button class="btn link small" style="margin-left:auto" data-action="detail" data-id="${p.id}">Lihat ${icon('chevron','sm')}</button></div>`).join(''):`<p class="small muted">Simpan produk dengan ikon bookmark agar mudah ditemukan lagi.</p><button class="btn soft small mt" data-route="catalog">Jelajahi katalog</button>`}</section><section class="panel"><h2>Aktivitas terakhir</h2>${state.history.length?state.history.slice(0,8).map(h=>`<div class="activity">${esc(h.text)}<time>${formatDate(h.date)}</time></div>`).join(''):'<p class="small muted mt">Aktivitas akan muncul setelah kamu mencari atau menyimpan produk.</p>'}</section></div><aside class="stack"><section class="panel"><div class="row">${icon('gift')}<h3>Kode referral teman</h3></div><p class="small muted mt">Kode demo untuk memperlihatkan alur referral. Tidak menghasilkan komisi sungguhan dalam prototipe.</p><div class="referral-code"><strong>MODALMATCH26</strong><button class="icon-btn" data-action="copy-referral" aria-label="Salin kode referral">${icon('copy','sm')}</button></div><p class="tiny muted mt">Dalam proyeksi bisnis, komisi referral diasumsikan Rp50.000 per rujukan yang berhasil dan memenuhi ketentuan mitra.</p></section><section class="panel"><h3>Rujukan ke bank</h3>${state.referrals.length?state.referrals.slice(0,4).map(r=>`<div class="activity"><strong>${esc(r.bank)} · ${esc(r.name)}</strong><time>${formatDate(r.date)}</time><span class="tag amber" style="margin-top:5px">${r.status}</span></div>`).join(''):'<p class="small muted mt">Belum ada rujukan demo. Pengajuan kredit hanya dilakukan melalui kanal resmi bank.</p>'}<p class="disclaimer">Klik atau rujukan demo tidak otomatis menghasilkan komisi. Belum ada kemitraan aktif yang diklaim.</p></section><section class="panel"><h3>Privasi dan kontrol akun</h3><p class="small muted mt">Data profil, simpanan, dan aktivitas disimpan di penyimpanan browser. Akun demo hanya berlaku pada browser ini dan bukan akun online ModalMatch.</p><button class="btn secondary full mt" data-action="logout">${icon('logout','sm')} Keluar dari akun</button><button class="btn link small mt" data-action="delete-data">${icon('trash','sm')} Hapus seluruh data lokal</button><button class="btn link small mt" data-route="revenue">Buka simulasi model bisnis ${icon('arrow','sm')}</button></section></aside></div>`;}
function sourcesView(){return `${heading('Transparan sejak sumbernya.','Data diperiksa 7 November 2026 · Pembaruan manual, bukan feed bank real-time.')}<div class="three-col mb"><div class="metric"><small>Verified</small><strong>20 entri</strong><span>Sumber resmi dapat ditelusuri; kelengkapan biaya terpisah.</span></div><div class="metric"><small>Produk aktif</small><strong>19 produk</strong><span>9 bank aktif; DBS disimpan sebagai arsip penghentian produk.</span></div><div class="metric"><small>Tanpa asumsi biaya nol</small><strong>20 / 20</strong><span>Memiliki informasi biaya atau ketentuan yang perlu dikonfirmasi.</span></div></div><div class="panel mb"><h2>Metodologi ModalMatch</h2><div class="faq"><details open><summary>Bagaimana produk dicocokkan?</summary><p>1. Hard filter: kategori, nominal, tenor sesuai tujuan, usia, penghasilan/umur usaha, dan agunan jika diketahui. 2. Kapasitas kas: cicilan dibandingkan dengan sisa kas dan batas model. 3. Klasifikasi: sesuai parameter, berpotensi sesuai/perlu konfirmasi, atau di luar parameter. 4. Pengurutan berdasarkan relevansi, estimasi cicilan, atau biaya diketahui. Data kosong tetap memerlukan konfirmasi. Tidak ada skor peluang persetujuan atau pengaruh komisi.</p></details><details><summary>Rumus bunga, biaya, dan dana bersih</summary><p>Flat: A = P/n + P × (bunga bulanan/100). Anuitas: A = P × r / (1−(1+r)^−n), r = bunga tahunan/1200. Efektif pokok tetap: A bulan t = P/n + saldo awal bulan × r. Suku bunga 0 menghasilkan P/n. Dana bersih ilustrasi = pokok − biaya yang diketahui dipotong pencairan; jika cara potong tidak jelas, nilai tidak dinyatakan pasti. EIR tahunan memakai IRR bulanan dipangkatkan 12, hanya bila seluruh arus kas diketahui. Untuk dataset ini biaya tidak lengkap, sehingga EIR final tidak ditampilkan.</p></details><details><summary>Apa arti label Verified dan Demo?</summary><p>Verified hanya berarti informasi pada sumber resmi sudah diperiksa. Bukan jaminan bahwa biaya lengkap, berlaku untuk semua profil, atau selalu terkini. Data bank yang belum ditemukan dinyatakan “perlu konfirmasi”. Profil pengguna, promosi Boost Produk Bank, pembayaran, referral, harga layanan, dan proyeksi pendapatan adalah Demo. Permata memakai dokumen 2024 dan wajib dikonfirmasi ulang.</p></details><details><summary>Pasar & peluang produk</summary><p>SNLIK OJK–BPS 2026 melaporkan literasi 69,57% dan inklusi 93,61% dengan 75.000 responden. Ini konteks nasional, bukan survei calon pengguna ModalMatch. Cermati sudah menyediakan pencarian kredit dan pembandingan. Hipotesis diferensiasi kami adalah integrasi kemampuan kas, biaya diketahui, stress test, sumber terbuka, dan penggunaan offline. Hipotesis belum diuji melalui riset pengguna langsung.</p><a href="research.html" target="_blank" rel="noopener" class="btn link small">Baca laporan riset dan sumber ${icon('external','sm')}</a></details><details><summary>Regulasi & batas prototipe</summary><p>Kajian mencakup POJK 4/2025 tentang PAJK, POJK 16/2025, POJK 30/2025 (berlaku 1 Juli 2026), POJK 22/2023, PADK 37/PADK.08/2025, serta UU 27/2022 PDP. Prototipe tidak mengklaim izin OJK atau kemitraan. Operasional komersial memerlukan kajian hukum, perizinan, persetujuan penggunaan data, serta perjanjian bank. Label akademik tidak otomatis mengecualikan kewajiban; termasuk pembatasan penyalinan konten untuk penyelenggaraan PAJK.</p></details><details><summary>Smart Funding Match & Securities Crowdfunding</summary><p>Menu Alternatif Pendanaan untuk UMKM membandingkan kredit bank/KUR dengan kesiapan SCF saham. Checklist SCF adalah asumsi internal prototipe, bukan skor OJK atau persetujuan penyelenggara. POJK 17 Tahun 2025 mengatur penawaran efek melalui layanan urun dana berbasis teknologi informasi, termasuk persyaratan penyelenggara, penerbit, pemodal, mitigasi risiko, tata kelola dan pelindungan pengguna. SCF dapat mencakup saham, efek bersifat utang, atau sukuk; prototipe ini hanya menghitung saham/dilusi. ModalMatch tidak menjadi penyelenggara dan tidak menghimpun dana.</p><p><a href="https://find.ojk.go.id/Home" target="_blank" rel="noopener">Verifikasi pelaku jasa keuangan melalui FIND OJK</a> · <a href="https://ojk.go.id/id/regulasi/Pages/POJK-17-Tahun-2025-Penawaran-Efek-Melalui-Layanan-Urun-Dana-Berbasis-Teknologi-Informasi.aspx" target="_blank" rel="noopener">Baca POJK 17/2025</a> · <a href="docs/crowdfunding.md" target="_blank" rel="noopener">Dokumentasi fitur</a>.</p></details></div></div><div class="section-head"><h2>Register sumber produk</h2><a class="btn secondary small" href="catalog.json" download="ModalMatch-katalog.json">${icon('download','sm')} Unduh data</a></div><div class="sources-list">${PRODUCTS.map(p=>`<article class="source-row"><span class="tag ${p.active?'green':'outline'}">${p.active?'Verified':'Arsip'}</span><h3>${esc(p.bank)} · ${esc(p.name)}</h3><p>${esc(p.notes)}</p><p><strong>Biaya:</strong> ${esc(p.feesText)}</p><p>${esc(p.rateConditions)}</p>${p.urls.map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener">Sumber resmi ${i+1} · ${new URL(url).hostname} ${icon('external','sm')}</a>`).join(' &nbsp; ')}<div class="tiny muted mt">Diperiksa ${p.checkedAt} · Biaya belum lengkap${p.sourceDate?' · Dokumen '+p.sourceDate:''}</div></article>`).join('')}</div>`;}
function revenueView(){
 const a=state.revenue;
 const years=a.years.map((y,i)=>({year:i+1,input:y,result:E.revenue({...y,price:a.price,commission:a.commission,boostMonthly:a.boostMonthly})}));
 const sum=years.reduce((acc,x)=>({revenue:acc.revenue+x.result.total,cost:acc.cost+x.result.operating,profit:acc.profit+x.result.surplus}),{revenue:0,cost:0,profit:0});
 const field=(label,key,value,step=1)=>`<div class="field"><label for="rev-${key}">${label}</label><input id="rev-${key}" type="number" min="0" step="${step}" value="${value}" data-revenue="${key}"></div>`;
 const yearCards=years.map(({year,input:y,result:r})=>`<section class="panel revenue-year"><div class="row between"><div><span class="tag ${year===1?'green':'outline'}">TAHUN ${year}</span><h3 style="margin-top:10px">Target pendapatan tahun ${year}</h3></div><strong class="revenue-total">${rupiah(r.total)}</strong></div><div class="revenue-mini-grid"><div><small>Penjualan laporan</small><strong>${rupiah(r.reportRevenue)}</strong></div><div><small>Referral</small><strong>${rupiah(r.referralRevenue)}</strong></div><div><small>Boost Produk Bank</small><strong>${rupiah(r.boostRevenue)}</strong></div></div><div class="fields mt"><div class="field"><label for="rev-${year}-reports">Jumlah laporan terjual</label><input id="rev-${year}-reports" type="number" min="0" step="10" value="${y.reports}" data-revenue-year="${year-1}" data-revenue-key="reports"></div><div class="field"><label for="rev-${year}-referrals">Referral berhasil</label><input id="rev-${year}-referrals" type="number" min="0" step="1" value="${y.referrals}" data-revenue-year="${year-1}" data-revenue-key="referrals"></div><div class="field"><label for="rev-${year}-banks">Mitra bank Boost</label><input id="rev-${year}-banks" type="number" min="0" step="1" value="${y.banks}" data-revenue-year="${year-1}" data-revenue-key="banks"></div><div class="field"><label for="rev-${year}-operating">Total biaya tahun ${year} (Rp)</label><input id="rev-${year}-operating" type="number" min="0" step="100000" value="${y.operating}" data-revenue-year="${year-1}" data-revenue-key="operating"></div></div><div class="revenue-result ${r.surplus>=0?'positive':'negative'}"><div><small>${r.surplus>=0?'Surplus / laba sebelum pajak':'Defisit simulasi'}</small><strong>${rupiah(r.surplus)}</strong></div><div><small>Minimal laporan untuk BEP*</small><strong>${r.reportsToBreakEven===null?'—':number(r.reportsToBreakEven)+' laporan'}</strong></div></div><p class="tiny muted mt">Asumsi mitra bank aktif selama 12 bulan penuh. *BEP dihitung setelah pendapatan referral dan Boost dikurangkan dari total biaya.</p></section>`).join('');
 const tableRows=years.map(({year,result:r})=>`<tr><td>Tahun ${year}</td><td>${rupiah(r.reportRevenue)}</td><td>${rupiah(r.referralRevenue)}</td><td>${rupiah(r.boostRevenue)}</td><td>${rupiah(r.total)}</td><td>${rupiah(r.operating)}</td><td>${rupiah(r.surplus)}</td></tr>`).join('');
 return `${heading('Tiga sumber pendapatan ModalMatch.','Simulasi bisnis berdasarkan asumsi dalam proposal. Ubah volume untuk melihat dampaknya.')}<div class="hint amber mb">${icon('info','sm')} Seluruh angka adalah target dan asumsi perencanaan, bukan pendapatan aktual atau kontrak mitra yang sudah disepakati.</div><div class="metric-grid"><div class="metric green"><small>Total pendapatan 3 tahun</small><strong>${rupiah(sum.revenue)}</strong><span>Penjualan laporan + referral + Boost</span></div><div class="metric"><small>Total biaya 3 tahun</small><strong>${rupiah(sum.cost)}</strong><span>Sesuai asumsi biaya tiap tahun</span></div><div class="metric"><small>Akumulasi laba sebelum pajak</small><strong style="color:${sum.profit<0?'var(--red)':'var(--emerald)'}">${rupiah(sum.profit)}</strong><span>Belum termasuk pajak dan biaya tak terduga</span></div></div><section class="panel mb"><div class="panel-head"><div><h2>Modal awal dan anggaran promosi</h2><p>Diselaraskan dengan rincian anggaran pada proposal ModalMatch.</p></div><span class="tag outline">Modal tetap</span></div><div class="revenue-mini-grid capital-grid"><div><small>Total modal awal</small><strong>Rp9.800.000</strong></div><div><small>Iklan digital + konten media sosial</small><strong>Rp500.000</strong></div><div><small>Sisa dana cadangan</small><strong>Rp400.000</strong></div></div><p class="tiny muted mt">Anggaran promosi Rp500.000 diambil dari pos cadangan, sehingga total kebutuhan modal awal tetap Rp9.800.000. Anggaran promosi mencakup iklan digital dan dukungan konten media sosial.</p></section><section class="panel mb"><div class="panel-head"><div><h2>Asumsi harga dan komisi</h2><p>Nilai dasar yang digunakan untuk ketiga tahun.</p></div></div><div class="fields">${field('Harga laporan (Rp)','price',a.price,1000)}${field('Komisi referral berhasil (Rp)','commission',a.commission,1000)}${field('Boost per bank per bulan (Rp)','boostMonthly',a.boostMonthly,50000)}</div></section><div class="section-head"><div><h2>Proyeksi per tahun</h2><p>Target mitra Boost Produk Bank: 1, 3, dan 5 bank.</p></div></div><div class="revenue-years">${yearCards}</div><section class="panel mt"><div class="panel-head"><div><h2>Ringkasan pendapatan dan BEP</h2><p>Semua sumber pendapatan diperhitungkan bersama.</p></div></div><div class="data-table-wrap"><table class="data-table revenue-table"><thead><tr><th>Periode</th><th>Laporan</th><th>Referral</th><th>Boost Bank</th><th>Total pendapatan</th><th>Total biaya</th><th>Laba sebelum pajak</th></tr></thead><tbody>${tableRows}</tbody></table></div><div class="hint mt"><strong>Contoh BEP tahun pertama:</strong> dengan 1 mitra bank aktif 12 bulan (Rp6.000.000) dan 20 referral berhasil (Rp1.000.000), diperlukan minimal ${number(years[0].result.reportsToBreakEven??0)} laporan terjual untuk menutup biaya tahun pertama sebesar ${rupiah(years[0].result.operating)}. Perhitungan ini memakai harga laporan ${rupiah(a.price)}.</div><p class="disclaimer mt">BEP merupakan pendekatan pendapatan gabungan: biaya tahunan dikurangi pendapatan referral dan Boost, lalu sisa kebutuhan ditutup dari penjualan laporan. Hasil aktual bergantung pada jumlah laporan yang dibayar, referral yang memenuhi syarat, lama kontrak bank, dan biaya yang benar-benar terjadi.</p></section>`;
}
function helpView(){return `${heading('Ada yang ingin kamu pahami?','Panduan singkat untuk menggunakan ModalMatch.')}<div class="two-col"><section class="panel faq"><h2>Pertanyaan yang sering muncul</h2>${[['Apa itu ModalMatch?','ModalMatch adalah prototipe aplikasi untuk membantu pengguna menemukan, membandingkan, dan memahami pilihan pembiayaan. Aplikasi tidak memberi pinjaman dan tidak mengambil keputusan kredit.'],['Bagaimana cara memulai?','Buat akun demo atau masuk, lalu pilih Cari Pembiayaan. Isi kebutuhan dana, batas cicilan, tenor, dan gambaran keuangan. Gunakan data contoh jika hanya ingin mencoba.'],['Apakah akun saya online?','Belum. Akun demo hanya tersimpan di browser dan perangkat yang digunakan. Belum ada server akun atau sinkronisasi lintas perangkat. Jangan gunakan kata sandi penting.'],['Apakah data bank nyata?','Nama produk, informasi publikasi, dan sumbernya berasal dari bank resmi yang tercantum dalam katalog. Tarif dan biaya dapat berubah; konfirmasi langsung ke bank sebelum mengambil keputusan.'],['Apakah pembayaran laporan benar-benar menagih?','Tidak. Harga rencana laporan adalah Rp25.000, tetapi checkout pada prototipe hanya simulasi. Tidak ada uang yang ditagihkan dan tidak ada data pembayaran sungguhan yang diminta.'],['Apa itu Boost Produk Bank?','Layanan promosi berbayar yang direncanakan untuk bank. Produk yang dipromosikan harus diberi label sponsor dan dipisahkan dari hasil pencocokan berdasarkan kemampuan finansial. Belum ada mitra berbayar yang diklaim dalam prototipe.'],['Bagaimana referral menghasilkan pendapatan?','Dalam proyeksi bisnis, komisi diasumsikan Rp50.000 per rujukan yang berhasil dan memenuhi ketentuan kerja sama. Klik atau rujukan demo di aplikasi ini tidak otomatis menghasilkan komisi.'],['Bagaimana Smart Funding Match bekerja?','Untuk profil UMKM, ModalMatch membandingkan produk bank/KUR dengan checklist kesiapan SCF saham. Hijau berarti parameter internal terpenuhi untuk dieksplorasi, bukan skor OJK atau persetujuan penyelenggara.'],['Bagaimana menggunakan secara offline?','Ekstrak paket ZIP lalu buka index.html. Katalog, pencarian, simulasi, perbandingan, dan laporan demo berjalan di browser. Tautan sumber bank memerlukan internet.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><aside class="stack"><section class="panel"><h3>Jelajahi dengan contoh</h3><p class="small muted mt">Gunakan profil contoh untuk melihat perbedaan pencarian pribadi dan UMKM. Angka dapat diubah sebelum menghitung.</p><button class="btn full mt" data-action="demo-journey" data-value="pribadi">Coba contoh karyawan ${icon('arrow','sm')}</button><button class="btn secondary full mt" data-action="demo-journey" data-value="umkm">Coba contoh UMKM ${icon('arrow','sm')}</button><button class="btn secondary full mt" data-action="no-result-demo">Lihat contoh tanpa hasil</button></section><section class="panel"><h3>Butuh informasi lebih lanjut?</h3><button class="btn link full mt" data-route="sources">Sumber dan metodologi ${icon('external','sm')}</button><button class="btn link full mt" data-route="revenue">Simulasi model bisnis ${icon('external','sm')}</button><a class="btn link full mt" href="research.html" target="_blank" rel="noopener">Riset dan dokumentasi ${icon('external','sm')}</a></section></aside></div>`;}
function formatDate(d){return new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(new Date(d));}

let modalReturnFocus=null;
function modal(content,wide=false){if(!$('#modal-root').children.length)modalReturnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${content.includes('Pembayaran')?'Pembayaran demo':'Detail ModalMatch'}"><button class="modal-close" data-action="close-modal" aria-label="Tutup dialog">${icon('close','sm')}</button>${content}</section></div>`;document.body.style.overflow='hidden';$('.modal-close').focus();}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';modalReturnFocus?.focus?.({preventScroll:true});}
function detail(id,tab='overview'){const p=PRODUCTS.find(p=>p.id===id);if(!p)return;const m=E.match(p,state.profile),c=m.cost;modal(`<div class="product-card-top">${bankLogo(p)}<div><h2>${esc(p.name)}</h2><p class="small muted">${esc(p.bank)} · ${p.category==='pribadi'?'Kredit pribadi':'Pembiayaan UMKM'}</p></div></div><div class="row wrap">${statusTag(m)}<span class="tag outline">Verified · diperiksa ${p.checkedAt}</span></div><div class="tab-strip">${[['overview','Ringkasan'],['cost','Biaya & cicilan'],['requirements','SyaratCheck'],['source','Sumber data']].map(([v,l])=>`<button class="${tab===v?'active':''}" data-action="detail-tab" data-id="${id}" data-value="${v}">${l}</button>`).join('')}</div>${tab==='overview'?`<div class="detail-grid"><div class="detail-box"><small>Plafon publikasi</small><strong>${p.minAmount?'Rp'+short(p.minAmount):'Min. konfirmasi'} – ${p.maxAmount?'Rp'+short(p.maxAmount):'konfirmasi'}</strong></div><div class="detail-box"><small>Tenor ${p.category==='umkm'?'modal kerja':''}</small><strong>${p.minTenor??'?'}–${p.maxTenor??'?'} bulan</strong>${p.investmentMaxTenor?`<p>Investasi hingga ${p.investmentMaxTenor} bulan</p>`:''}</div><div class="detail-box"><small>Bunga publikasi</small><strong>${esc(p.rateText)}</strong></div><div class="detail-box"><small>Agunan</small><p>${esc(p.collateral)}</p></div></div><div class="detail-section"><h3>Mengapa status ini muncul?</h3><ul>${m.failed.map(x=>`<li style="color:var(--red)">${esc(x)}</li>`).join('')}${m.passed.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="hint amber"><div>${esc(p.rateConditions)}<br><span class="tiny">Biaya belum lengkap. Status bukan jaminan persetujuan.</span></div></div>`:''}${tab==='cost'?`<p class="small muted">Ilustrasi ${rupiah(state.profile.amount)} · ${state.profile.tenor} bulan. ${m.failed.length?'Parameter ini belum memenuhi seluruh batas produk.':''}</p><div class="detail-grid"><div class="detail-box"><small>Estimasi cicilan / bulan</small><strong>${c.installment===null?'Perlu konfirmasi':rupiah(c.installment)}</strong></div><div class="detail-box"><small>Total angsuran</small><strong>${c.total===null?'Belum dihitung':rupiah(c.total)}</strong></div><div class="detail-box"><small>Total bunga ilustrasi</small><strong>${c.interest===null?'Belum dihitung':rupiah(c.interest)}</strong></div><div class="detail-box"><small>Biaya awal diketahui</small><strong>${c.knownFeeCount?rupiah(c.knownFee):'Belum diketahui'}</strong></div><div class="detail-box"><small>Dana diterima setelah biaya diketahui</small><strong>${c.net===null?'Cara potong belum pasti':rupiah(c.net)}</strong></div><div class="detail-box"><small>Angsuran + biaya diketahui</small><strong>${c.knownTotal===null?'Belum dihitung':rupiah(c.knownTotal)}</strong></div></div><div class="hint amber">${icon('info','sm')} Total final dan biaya efektif tahunan belum dapat ditetapkan karena biaya tidak lengkap. Dana bersih dapat lebih kecil bila ada potongan tambahan.</div><div class="detail-section"><h3>Rincian biaya & perlakuan</h3><p>${esc(p.feesText)}</p><p>${p.feeTreatment==='deducted'?'Biaya awal diketahui dipotong dari pencairan.':p.feeTreatment==='separate'?'Biaya diketahui dibayar terpisah.':'Cara pembayaran/pemotongan biaya harus dikonfirmasi.'}</p><p>${esc(p.calculationNote||p.rateConditions)}</p></div>${c.rows.length?`<details class="detail-section"><summary class="small" style="cursor:pointer;font-weight:600">Lihat jadwal ${c.rows.length} angsuran ilustrasi</summary><p>${p.indicativeFlat?'Rincian pokok/bunga berikut hanya model flat ilustratif, bukan jadwal amortisasi kontrak bank.':'Model menggunakan periode bulanan. Pembulatan dan tanggal aktual bank dapat berbeda.'}</p><div class="data-table-wrap mt" style="max-height:300px"><table class="data-table" style="min-width:440px"><thead><tr><th>Bulan</th><th>Pokok</th><th>Bunga</th><th>Angsuran</th><th>Sisa</th></tr></thead><tbody>${c.rows.map(r=>`<tr><td>${r.month}</td><td>${rupiah(r.principal)}</td><td>${rupiah(r.interest)}</td><td>${rupiah(r.payment)}</td><td>${rupiah(r.balance)}</td></tr>`).join('')}</tbody></table></div></details>`:''}`:''}${tab==='requirements'?`<div class="hint">${icon('shield','sm')} SyaratCheck membaca input demo, bukan dokumen asli atau SLIK. Checklist hanya membantu persiapan.</div><ul class="validation-list">${m.passed.map(x=>`<li>${icon('check')}<div>${esc(x)}<br><span class="tag green">Terpenuhi berdasarkan input</span></div></li>`).join('')}${m.failed.map(x=>`<li>${icon('close')}<div>${esc(x)}<br><span class="tag red">Belum terpenuhi</span></div></li>`).join('')}${p.requirements.map(x=>`<li>${icon('help')}<div>${esc(x)}<br><span class="tag amber">Perlu verifikasi bank</span></div></li>`).join('')}</ul><h3>Checklist dokumen demo</h3><div class="stack mt">${p.documents.map((d,i)=>`<label class="check-line"><input type="checkbox" data-doc="${p.id}:${i}" ${state.docChecks?.[p.id+':'+i]?'checked':''}>${esc(d)} <span class="tiny muted">— kesiapan menurutmu, belum diverifikasi</span></label>`).join('')}</div>`:''}${tab==='source'?`<div class="detail-section"><h3>Riwayat dan keterbatasan</h3><p>${esc(p.notes)}</p><p>Status Verified berarti sumber diperiksa. Kelengkapan informasi dan keberlakuan tarif untuk masing-masing pemohon tetap perlu konfirmasi.</p><p>Terakhir diperiksa: ${p.checkedAt}${p.sourceDate?' · Versi dokumen: '+p.sourceDate:''}</p></div><div class="stack">${p.urls.map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener" class="btn secondary" style="white-space:normal">Sumber resmi ${i+1} · ${new URL(url).hostname} ${icon('external','sm')}</a>`).join('')}</div><div class="detail-section"><h3>Informasi yang belum lengkap</h3><ul>${m.unknown.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<div class="divider"></div><div class="row wrap between">${button(state.saved.includes(id)?'Tersimpan '+icon('check','sm'):'Simpan produk '+icon('bookmark','sm'),'save','secondary',`data-id="${id}" data-detail="${tab}"`)}${p.active?button('Lanjut ke bank '+icon('external','sm'),'bank-referral','',`data-id="${id}"`):'<span class="tag outline">Pengajuan baru ditutup</span>'}</div><p class="disclaimer">ModalMatch tidak memiliki kerja sama referral aktif. Pengajuan dan keputusan pembiayaan berada pada bank.</p>`,true);}
function checkout(){if(validateProfile()){toast('Lengkapi profil valid sebelum membuat laporan.');go('finder');return;}state.checkout={method:'QRIS demo',referral:'',profile:JSON.parse(JSON.stringify(state.profile)),risk:{...state.risk},productId:selectedProduct()?.id,step:'select'};drawCheckout();}
function drawCheckout(){const c=state.checkout;if(!c)return;modal(`<span class="tag amber">SIMULASI · TANPA TAGIHAN</span><h2 style="margin-top:16px">Checkout Laporan ModalMatch</h2><p>Laporan personal untuk profil ${c.profile.category==='pribadi'?'karyawan':'UMKM'} · ${rupiah(c.profile.amount)}.</p><div class="receipt"><div class="summary-row"><span>Laporan finansial ModalMatch</span><strong>Rp25.000</strong></div><div class="summary-row"><span>Biaya layanan demo</span><strong>Rp0</strong></div><div class="summary-row"><span>Total simulasi</span><strong class="checkout-total">Rp25.000</strong></div></div><h3 style="font-size:13px">Metode pembayaran simulasi</h3>${[['QRIS demo','Tampilan kode demonstrasi · tidak dapat dibayar'],['Virtual account demo','Pengenal transfer fiktif · tidak menerima dana'],['Dompet digital demo','Konfirmasi dalam prototipe']].map(([l,d])=>`<label class="checkout-method ${c.method===l?'selected':''}"><input type="radio" name="payment-method" value="${l}" ${c.method===l?'checked':''}><span>${icon(l.includes('account')?'building':'wallet')}</span><span><strong>${l}</strong><small>${d}</small></span></label>`).join('')}<div class="field mt"><label for="checkout-referral">Kode referral teman (opsional)</label><input id="checkout-referral" placeholder="Contoh: MODALMATCH26" value="${esc(c.referral)}" maxlength="30"><small>Demonstrasi atribusi teman; tidak memberikan diskon atau hadiah.</small></div><div id="referral-feedback" class="tiny mt"></div><div class="hint mt">${icon('info','sm')} Tidak diperlukan rekening, kartu, PIN, atau OTP asli.</div>${button('Lanjutkan pembayaran demo '+icon('arrow','sm'),'payment-next','full mt')}`);}
function paymentStep(){const c=state.checkout;if(!c)return;c.referral=($('#checkout-referral')?.value||c.referral||'').trim().toUpperCase();if(c.referral&&!['MODALMATCH26'].includes(c.referral)){toast('Kode referral demo tidak dikenali. Gunakan MODALMATCH26 atau kosongkan.');return;}c.step='pending';modal(`<div class="centered"><span class="tag amber">PEMBAYARAN DEMO</span><h2 style="margin:18px 0 8px">Menunggu konfirmasi simulasi</h2><p class="small muted">Laporan ModalMatch · ${c.method}</p>${c.method==='QRIS demo'?'<div class="qr-demo" role="img" aria-label="Pola ilustratif bukan QRIS aktif"><span>DEMO ONLY</span></div>':`<div class="receipt centered"><span class="tiny muted">${c.method.includes('account')?'PENGENAL DEMO, BUKAN REKENING':'DOMPET DIGITAL SIMULASI'}</span><h3 style="font-size:23px;margin:15px">${c.method.includes('account')?'DEMO–MM–25000':'ModalMatch Demo Wallet'}</h3></div>`}<strong class="checkout-total">Rp25.000</strong><p class="tiny muted" style="margin:15px 0">Pola di atas tidak bisa dipakai untuk transfer.<br>Pilih hasil transaksi untuk mendemonstrasikan alur.</p></div>${button('Simulasikan pembayaran berhasil '+icon('check','sm'),'payment-success','full')}${button('Simulasikan pembayaran gagal','payment-fail','secondary full mt')}`);}
function paymentSuccess(){const c=state.checkout;if(!c||c.step!=='pending')return;c.step='success';const report={id:'MM-'+Date.now().toString(36).toUpperCase(),date:new Date().toISOString(),profile:c.profile,risk:c.risk,productId:c.productId,method:c.method,referral:c.referral,paid:25000,userName:currentUserName(),status:'Demo berhasil'};state.reports.unshift(report);activity('Pembayaran demo berhasil; laporan '+report.id+' dibuat.');modal(`<div class="centered"><div class="success-symbol">${icon('check')}</div><span class="tag green">TRANSAKSI DEMO BERHASIL</span><h2 style="margin:16px 0 12px">Laporanmu siap dibaca.</h2><p class="small muted">Simulasi selesai. Tidak ada uang yang dibayarkan.</p></div><div class="receipt"><div class="summary-row"><span>ID laporan</span><strong>${report.id}</strong></div><div class="summary-row"><span>Metode</span><strong>${esc(c.method)}</strong></div><div class="summary-row"><span>Total demo</span><strong>Rp25.000</strong></div>${c.referral?`<div class="summary-row"><span>Atribusi teman demo</span><strong>${esc(c.referral)}</strong></div>`:''}</div>${button('Buka laporan '+icon('report','sm'),'open-report','full',`data-id="${report.id}"`)}`);render();}
function paymentFail(){if(!state.checkout)return;state.checkout.step='failed';modal(`<div class="centered"><div class="success-symbol" style="background:#fcebed;color:var(--red)">${icon('close')}</div><span class="tag red">TRANSAKSI DEMO GAGAL</span><h2 style="margin:16px 0">Pembayaran belum berhasil.</h2><p class="small muted">Ini state simulasi kegagalan. Tidak ada saldo yang terpotong dan laporan belum terbuka.</p></div>${button('Coba lagi','retry-payment','full mt')}${button('Kembali ke laporan','close-to-reports','secondary full mt')}`);}
function reportHtml(report){const p=report.profile,h=E.health(p),s=E.health(p,report.risk),rows=listMatches(p),product=PRODUCTS.find(x=>x.id===report.productId)||rows[0]?.product,selected=product?E.cost(product,p.amount,p.tenor):null;
return `<span class="tag green">LAPORAN MODALMATCH · SNAPSHOT DEMO</span><h1 style="margin-top:16px">Ringkasan finansial ${esc(report.userName||currentUserName())}</h1><p class="small muted">${report.id} · ${formatDate(report.date)} · Profil fiktif ${p.category==='pribadi'?'karyawan':'UMKM'}</p><h2 style="margin-top:24px">01 · Gambaran finansial</h2><div class="detail-grid"><div class="detail-box"><small>Kebutuhan dana / tenor</small><strong>${rupiah(p.amount)} / ${p.tenor} bulan</strong></div><div class="detail-box"><small>Kapasitas angsuran model</small><strong>${rupiah(h.capacity)}</strong></div><div class="detail-box"><small>Pemasukan ${p.category==='pribadi'?'bersih':'omzet'}</small><strong>${rupiah(h.incoming)}</strong></div><div class="detail-box"><small>Biaya rutin + penarikan pemilik</small><strong>${rupiah(h.expenses)}</strong></div><div class="detail-box"><small>Cicilan lama / cadangan bulanan</small><strong>${rupiah(h.debt)} / ${rupiah(p.reserve)}</strong></div><div class="detail-box"><small>Sisa kas sebelum pinjaman baru</small><strong>${rupiah(h.available)}</strong></div></div><h2>02 · Pilihan & biaya diketahui</h2><p class="disclaimer">Bukan penawaran atau persetujuan. Semua biaya belum lengkap; “—” berarti tidak dapat dihitung.</p><div class="data-table-wrap mt"><table class="data-table" style="min-width:560px"><thead><tr><th>Produk</th><th>Status</th><th>Cicilan</th><th>Angsuran + biaya diketahui</th></tr></thead><tbody>${rows.map(m=>`<tr><td><strong>${esc(m.product.bank+' '+m.product.name)}</strong></td><td>${m.status==='fit'?'Sesuai parameter':m.status==='no'?'Di luar parameter':'Perlu konfirmasi'}</td><td>${m.cost.installment===null?'—':rupiah(m.cost.installment)}</td><td>${m.cost.knownTotal===null?'—':rupiah(m.cost.knownTotal)}</td></tr>`).join('')}</tbody></table></div><h2 style="margin-top:24px">03 · Uji ketahanan</h2><p class="small muted mt">Skenario: pemasukan turun ${report.risk.incomeDrop}%, biaya naik ${report.risk.costRise}%, kewajiban tambahan ${rupiah(report.risk.extraDebt)}, cadangan terpakai ${rupiah(report.risk.reserveDraw)}. ${p.category==='umkm'?'Biaya variabel menurun proporsional terhadap omzet, biaya tetap dipertahankan.':''}</p><div class="detail-grid"><div class="detail-box"><small>Kas tersedia setelah skenario</small><strong>${rupiah(s.available)}</strong></div><div class="detail-box"><small>Kapasitas setelah skenario</small><strong>${rupiah(s.capacity)}</strong></div></div><p class="small">${selected?.installment!=null?`${esc(product.bank+' '+product.name)}: cicilan ilustrasi ${rupiah(selected.installment)}. Sisa kas setelah cicilan dan skenario ${rupiah(s.available-selected.installment)}. ${selected.installment>s.capacity?'Rencana melampaui kapasitas skenario.':'Masih dalam batas kapasitas skenario.'}`:'Belum ada produk dengan cicilan terhitung untuk stress test.'}</p><h2 style="margin-top:24px">04 · Alternatif & langkah berikutnya</h2>${(()=>{const a=product?E.alternative(product,{...p,maxInstallment:Math.min(p.maxInstallment,s.capacity)}):null;return `<p class="small muted mt">${a?`Alternatif nominal ${rupiah(a.amount)} selama ${a.tenor} bulan: angsuran ilustrasi ${rupiah(a.installment)} dengan bunga model ${number(a.rate)}%/tahun, metode ${a.product.method}, penyangga kapasitas 5%. Biaya lain belum lengkap.`:'Belum ada alternatif nominal yang lolos batas dasar. Perbaiki arus kas atau tunda pengajuan.'}</p>`;})()}<p class="small muted mt">1. Pastikan dana darurat tersedia. 2. Minta RIPLAY personal dari bank. 3. Konfirmasi bunga, potongan pencairan, asuransi, serta pelunasan dini. 4. Periksa dokumen dan kriteria khusus. 5. Putuskan berdasarkan keseluruhan biaya dan ruang kas.</p><h2 style="margin-top:24px">05 · Sumber, asumsi & batasan</h2><p class="small muted mt">Data diperiksa 7 November 2026; pembaruan manual. Model pribadi menggunakan batas perencanaan 35% penghasilan, UMKM DSCR 1,25×. Flat: P/n + P×bunga bulanan. Anuitas: P×r/(1−(1+r)^−n). Ukuran biaya efektif final tidak dihitung bila biaya belum lengkap. Hasil berbeda dari bank bila tarif, pembulatan, periode, atau biaya berubah.</p>${rows.map(m=>`<p class="tiny muted" style="margin:12px 0"><strong>${esc(m.product.bank+' '+m.product.name)}:</strong> ${esc(m.product.rateConditions)} ${esc(m.product.feesText)}<br>${m.product.urls.map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(u)}</a>`).join('<br>')}</p>`).join('')}<p class="disclaimer">Prototipe akademik, bukan bank/PAJK berizin, bukan nasihat atau keputusan kredit resmi. Profil dan transaksi fiktif; tidak ada kemitraan bank atau dana yang ditagihkan.</p>`;}
function openReport(id){const r=state.reports.find(x=>x.id===id);if(!r)return;modal(reportHtml(r)+`<div class="row wrap mt">${button('Cetak / simpan PDF '+icon('download','sm'),'print-report','',`data-id="${id}"`)}${button('Unduh snapshot JSON','export-report','secondary',`data-id="${id}"`)}</div>`,true);}
function bankReferral(id){const p=PRODUCTS.find(x=>x.id===id&&x.active);if(!p)return;modal(`<span class="tag amber">REFERRAL DEMO</span><h2 style="margin-top:16px">Lanjut ke kanal resmi ${esc(p.bank)}</h2><p>Kamu memilih ${esc(p.name)}. Pengajuan, verifikasi dokumen, dan keputusan kredit dilakukan oleh bank.</p><div class="hint">${icon('external','sm')} Tujuan: ${esc(new URL(p.urls[0]).hostname)}</div><div class="detail-section"><h3>Transparansi rujukan</h3><p>ModalMatch belum memiliki kerja sama komersial dengan bank ini. Konfirmasi hanya mencatat status rujukan demo secara lokal; tidak mengirim profil atau pengajuan. Komisi Rp50.000 di modul bisnis hanyalah asumsi untuk rujukan yang kelak memenuhi perjanjian.</p></div><div class="row wrap">${button('Konfirmasi rujukan demo','confirm-referral','',`data-id="${id}"`)}${button('Kembali','detail','secondary',`data-id="${id}"`)}</div>`);}
function confirmReferral(id){const p=PRODUCTS.find(x=>x.id===id);if(!p)return;state.referrals.unshift({id:'REF-'+Date.now().toString(36).toUpperCase(),bank:p.bank,name:p.name,date:new Date().toISOString(),status:'Rujukan disiapkan · demo'});activity('Rujukan demo disiapkan untuk '+p.bank+' '+p.name+'. Tidak ada pengajuan dikirim.');modal(`<div class="success-symbol">${icon('check')}</div><h2>Rujukan demo disiapkan.</h2><p>Tidak ada data yang dikirim ke bank dan tidak ada komisi tercatat. Buka sumber resmi untuk membaca ketentuan aktual.</p><a class="btn full" href="${esc(p.urls[0])}" target="_blank" rel="noopener">Buka situs resmi ${esc(p.bank)} ${icon('external','sm')}</a><button class="btn secondary full mt" data-route="profile">Lihat riwayat rujukan</button>`);render();}
const articles={flat:{title:'Bunga flat dan efektif: lihat arus kasnya.',body:'Bunga flat dihitung dari pokok awal sepanjang tenor. Bunga efektif dihitung dari sisa pokok. Pada anuitas, total cicilan tetap tetapi komposisi bunga dan pokok berubah. Karena dasar perhitungannya berbeda, 1% flat per bulan tidak sama dengan 12% efektif per tahun. Bandingkan cicilan, total angsuran, dana bersih, dan seluruh biaya pada nominal serta tenor yang sama.',example:'Contoh BCA retail Rp30 juta / 36 bulan pada 1,07% flat per bulan: pokok bulanan Rp833.333 + bunga Rp321.000 = Rp1.154.333/bulan. Tarif bergantung tenor dan segmen.'},cost:{title:'Cicilan bukan satu-satunya biaya.',body:'Periksa provisi, administrasi, meterai, asuransi, biaya rekening, agunan, serta penalti. Sebagian dipotong dari pencairan, sebagian dibayar terpisah. Biaya yang belum dipublikasikan bukan berarti nol. Minta RIPLAY personal sebelum membuat keputusan.',example:'Contoh Rp30 juta BCA: provisi 1% Rp300.000 dan meterai Rp10.000 diketahui dipotong. Dana setelah potongan diketahui Rp29.690.000; asuransi opsional dan kondisi lain dapat mengubah hasil akhir.'},umkm:{title:'Omzet bukan kemampuan bayar.',body:'Omzet adalah pendapatan kotor. Kemampuan membayar berasal dari kas setelah bahan baku, biaya tetap, penarikan pemilik, cicilan berjalan, dan cadangan. Saat omzet turun, sebagian biaya variabel ikut turun tetapi sewa atau gaji tetap belum tentu berubah.',example:'Contoh demo: omzet Rp40 juta − biaya variabel Rp18 juta − tetap Rp8 juta − penarikan Rp4 juta − cadangan Rp3 juta − cicilan Rp1 juta = kas Rp6 juta. Omzet turun 20% menghasilkan kas Rp1,6 juta, bukan sekadar Rp6 juta dikurangi 20%.'}};
function article(id){const a=articles[id];if(!a)return;modal(`<span class="tag green">MODALMATCH EDUKASI</span><h2 style="margin-top:18px">${a.title}</h2><p>${a.body}</p><div class="hint">${icon('book','sm')}${a.example}</div><button class="btn full mt" data-route="analysis">Coba pada analisismu ${icon('arrow','sm')}</button><p class="disclaimer">Edukasi umum untuk prototipe. Sumber bank dan rumus lengkap tersedia pada Sumber & Metodologi.</p>`);}
function downloadJson(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function onboarding(){modal(`<span class="tag green">SELAMAT DATANG DI MODALMATCH</span><h2 style="margin-top:17px">Kenali pilihan. Temukan arah.</h2><p>Mulai dengan profil demo. Semua perhitungan berjalan di perangkatmu.</p>${[['search','Ceritakan kebutuhanmu','Isi nominal, tenor, dan kondisi keuangan.'],['compare','Pahami pilihan & biayanya','Sumber bank dan asumsi bisa kamu telusuri.'],['chart','Uji rencanamu','Lihat dampak perubahan penghasilan atau omzet.']].map(([i,t,d])=>`<div class="onboarding-step"><span class="stat-icon">${icon(i)}</span><div><strong>${t}</strong><small>${d}</small></div></div>`).join('')}<p class="disclaimer">Prototipe akademik. Tidak menerima pengajuan atau pembayaran sungguhan.</p>${button('Mulai dengan profil demo '+icon('arrow','sm'),'finish-onboarding','full mt')}`);}
document.addEventListener('click',async event=>{
 const route=event.target.closest('[data-route]');if(route){go(route.dataset.route);return;}
 const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,v=el.dataset.value;
 switch(a){
 case 'auth-open-signup':state.authError='';renderAuth('signup');break;
 case 'auth-open-login':state.authError='';renderAuth('login');break;
 case 'auth-back':state.authError='';renderAuth('welcome');break;
 case 'auth-guest':enterGuest();break;
 case 'logout':logout();break;
 case 'close-modal':closeModal();break;
 case 'start-finder':if(!state.seen)onboarding();else go('finder');break;
 case 'finish-onboarding':state.seen=true;persist();go('finder');break;
 case 'category':if(v==='roadmap')modal(`<span class="tag outline">ROADMAP</span><h2 style="margin-top:18px">Sedang dipersiapkan.</h2><p>KPR dan kendaraan belum memiliki mesin perhitungan di prototipe ini. Saat ini ModalMatch berfokus pada kredit pribadi dan pembiayaan UMKM.</p><button class="btn" data-route="finder">Jelajahi kategori aktif</button>`);else{setCategory(v);go('finder');}break;
 case 'switch-profile':setCategory(v);state.formError='';render();break;
 case 'load-demo':setCategory(state.profile.category);state.formError='';render();toast('Profil contoh dimuat. Semua angka bisa diubah.');break;
 case 'demo-journey':setCategory(v);go('finder');break;
 case 'use-umkm-demo':setCategory('umkm');state.funding.raiseAmount=state.profile.amount;go('funding');break;
 case 'funding-bank-catalog':state.category='umkm';state.bank='all';state.search='';go('catalog');break;
 case 'funding-sync-amount':state.funding.raiseAmount=state.profile.amount;persist();render();toast('Target pendanaan disamakan dengan kebutuhan modal.');break;
 case 'no-result-demo':setCategory(state.profile.category);state.profile.maxInstallment=100000;state.profile.amount=2000000000;persist();go('results');break;
 case 'detail':detail(id);break;
 case 'detail-tab':detail(id,v);break;
 case 'save':if(state.saved.includes(id)){state.saved=state.saved.filter(x=>x!==id);toast('Produk dihapus dari tersimpan.');}else{state.saved.push(id);activity('Menyimpan '+PRODUCTS.find(p=>p.id===id)?.name);toast('Produk tersimpan di perangkatmu.');}persist();render();if(el.dataset.detail)detail(id,el.dataset.detail);break;
 case 'clear-compare':state.compare=[];persist();render();break;
 case 'remove-compare':state.compare=state.compare.filter(x=>x!==id);persist();render();break;
 case 'go-compare':go('compare');break;
 case 'go-analysis':go('analysis');break;
 case 'go-sources':go('sources');break;
 case 'edit-finder':go('finder');break;
 case 'catalog-category':state.category=v;render();break;
 case 'result-filter':state.resultsFilter=v;render();break;
 case 'reset-filters':state.search='';state.category='all';state.bank='all';state.filterAmount=state.filterTenor=0;state.sort='relevant';render();break;
 case 'apply-alternative':state.profile.amount=Number(el.dataset.amount);persist();activity('Mengubah nominal simulasi ke '+rupiah(state.profile.amount));go('results');break;
 case 'reset-risk':state.risk={incomeDrop:0,costRise:0,extraDebt:0,reserveDraw:0};render();break;
 case 'checkout':checkout();break;
 case 'payment-next':paymentStep();break;
 case 'payment-success':paymentSuccess();break;
 case 'payment-fail':paymentFail();break;
 case 'retry-payment':state.checkout.step='select';drawCheckout();break;
 case 'close-to-reports':go('reports');break;
 case 'open-report':openReport(id);break;
 case 'report-preview':modal(`<span class="tag green">CONTOH ISI LAPORAN</span><h2 style="margin-top:16px">Dari data menjadi rencana.</h2><p>Laporan menyimpan snapshot profil pada saat transaksi demo berhasil.</p><ul class="validation-list">${['Ringkasan pemasukan, biaya, cicilan dan cadangan','Kapasitas model dan rasio kewajiban','Tabel produk dengan biaya diketahui dan keterbatasan','Stress test sesuai skenario yang dipilih','Alternatif nominal berdasarkan perhitungan','Langkah persiapan, asumsi, dan sumber resmi'].map(t=>`<li>${icon('check')}${t}</li>`).join('')}</ul>${button('Coba pembelian demo · Rp25.000','checkout','full mt')}`);break;
 case 'print-report':{const r=state.reports.find(x=>x.id===id);if(r){document.querySelector('.print-report')?.remove();const n=document.createElement('section');n.className='print-report';n.innerHTML=reportHtml(r);document.body.appendChild(n);window.print();}break;}
 case 'export-report':{const r=state.reports.find(x=>x.id===id);if(r)downloadJson('ModalMatch-'+id+'.json',r);break;}
 case 'bank-referral':bankReferral(id);break;
 case 'confirm-referral':confirmReferral(id);break;
 case 'copy-referral':try{await navigator.clipboard.writeText('MODALMATCH26');toast('Kode MODALMATCH26 disalin.');}catch(e){modal('<h2>Kode referral temanmu</h2><p>Pilih dan salin kode ini untuk demonstrasi:</p><div class="referral-code"><strong>MODALMATCH26</strong></div>');}break;
 case 'sponsor':modal(`<span class="tag amber">CONTOH BOOST · SIMULASI</span><h2 style="margin-top:17px">Boost Produk Bank</h2><p>Dalam model bisnis ModalMatch, bank dapat membayar biaya promosi agar produk pembiayaannya memperoleh penempatan khusus dan visibilitas lebih tinggi di aplikasi.</p><div class="hint">${icon('shield','sm')} Produk yang dipromosikan harus diberi label sponsor dan tidak boleh memengaruhi perhitungan kecocokan atau hasil rekomendasi berdasarkan kemampuan finansial.</div><div class="detail-section"><h3>Asumsi proposal</h3><p>Biaya pengenalan sebesar Rp500.000 per bank per bulan. Target mitra adalah 1 bank pada tahun pertama, 3 bank pada tahun kedua, dan 5 bank pada tahun ketiga.</p></div><p class="disclaimer">Ini hanya contoh tampilan. Belum ada bank yang diklaim telah membayar atau menjadi mitra ModalMatch.</p>`);break;
 case 'article':article(id);break;
 case 'notifications':modal(`<h2>Kabar dari ModalMatch</h2><div class="history-row"><span class="stat-icon">${icon('shield')}</span><div><p>Katalog produk sudah diperiksa</p><small>7 November 2026 · 19 produk aktif + 1 arsip</small></div></div><div class="history-row"><span class="stat-icon">${icon('info')}</span><div><p>DBS KTA masuk arsip</p><small>Tidak menerima KTA baru sejak 1 Agustus 2026.</small></div></div><p class="disclaimer">Pemberitahuan produk statis untuk prototipe, bukan notifikasi dari bank.</p>`);break;
 case 'delete-data':modal(`<h2>Hapus data di perangkat ini?</h2><p>Akun demo, profil, produk tersimpan, laporan, checklist, dan riwayat referral akan dihapus dari browser ini. Katalog bank tetap tersedia.</p>${button('Hapus data lokal','confirm-delete','danger full')}${button('Batal','close-modal','secondary full mt')}`);break;
 case 'confirm-delete':try{localStorage.removeItem('modalmatch-v1');localStorage.removeItem('kk-v1')}catch(e){}state.auth=null;state.profile={...personal};state.saved=[];state.compare=[];state.reports=[];state.referrals=[];state.history=[];state.docChecks={};state.seen=false;state.checkout=null;closeModal();renderAuth('welcome');toast('Data lokal telah dihapus.');break;
 case 'reset-revenue':state.revenue={price:25000,commission:50000,boostMonthly:500000,years:[{reports:300,referrals:20,banks:1,operating:9400000},{reports:600,referrals:40,banks:3,operating:6700000},{reports:900,referrals:60,banks:5,operating:8500000}]};render();toast('Asumsi proyeksi dikembalikan sesuai proposal.');break;
 }
});
document.addEventListener('submit',async e=>{if(e.target.id==='signup-form'){e.preventDefault();await registerAccount(e.target);return;}if(e.target.id==='login-form'){e.preventDefault();await loginAccount(e.target);return;}if(e.target.id==='global-search'){e.preventDefault();state.search=new FormData(e.target).get('query').trim();state.category='all';state.bank='all';go('catalog');}if(e.target.id==='finder-form'){e.preventDefault();updateForm(e.target);state.formError=validateProfile();if(state.formError){render();window.scrollTo({top:0});return;}persist();activity('Menjalankan pencarian '+state.profile.category+' '+rupiah(state.profile.amount)+' / '+state.profile.tenor+' bulan.');state.resultsFilter='all';state.sort='relevant';go('results');}});
document.addEventListener('input',e=>{const el=e.target;if(el.closest('#finder-form'))updateForm(el.closest('form'));if(el.id==='catalog-search'){state.search=el.value;render();}if(el.id==='amount-filter'){state.filterAmount=Math.max(0,Number(el.value)||0);render();}if(el.dataset.risk){state.risk[el.dataset.risk]=E.clamp(Number(el.value)||0,0,el.type==='range'?80:1e12);render();}if(el.dataset.revenue){state.revenue[el.dataset.revenue]=E.clamp(Number(el.value)||0,0,1e12);render();}if(el.dataset.revenueYear!==undefined){const year=Number(el.dataset.revenueYear),key=el.dataset.revenueKey;if(state.revenue.years[year]&&key)state.revenue.years[year][key]=E.clamp(Number(el.value)||0,0,1e12);render();}if(el.dataset.fundingNumber){state.funding[el.dataset.fundingNumber]=E.clamp(Number(el.value)||0,0,1e12);persist();render();}if(el.id==='checkout-referral'&&state.checkout)state.checkout.referral=el.value;});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.compare){const id=el.dataset.compare;if(el.checked){if(state.compare.length>=3){el.checked=false;toast('Maksimal 3 produk untuk perbandingan.');return;}if(!state.compare.includes(id))state.compare.push(id);}else state.compare=state.compare.filter(x=>x!==id);persist();render();}if(el.id==='bank-filter'){state.bank=el.value;render();}if(el.id==='catalog-sort'||el.id==='results-sort'){state.sort=el.value;render();}if(el.id==='tenor-filter'){state.filterTenor=Number(el.value);render();}if(el.id==='risk-product'){state.riskProduct=el.value;persist();render();}if(el.name==='payment-method'){state.checkout.method=el.value;drawCheckout();}if(el.dataset.funding){state.funding[el.dataset.funding]=el.value;persist();render();}if(el.dataset.doc){state.docChecks=state.docChecks||{};state.docChecks[el.dataset.doc]=el.checked;persist();}if(el.closest('#finder-form')){updateForm(el.closest('form'));persist();}});
document.addEventListener('keydown',e=>{const current=$('.modal');if(!current)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const focusable=[...current.querySelectorAll('button:not([disabled]),a,input,select,summary,textarea')].filter(n=>n.offsetParent!==null),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(routes[r]&&r!==state.route){state.route=r;closeModal();render();window.scrollTo(0,0);}});
window.addEventListener('offline',render);window.addEventListener('online',render);render();
